function crawlCompany(c){const base=(c.company_name+" "+c.industry+" "+c.raw_tags.join(" ")+" "+(c.website_url||"")).toLowerCase();const result={manufacturers:[],technologies:[],business_areas:[]},ev=[];for(const group of Object.keys(TAG_MAP))for(const [canon,terms] of Object.entries(TAG_MAP[group])){const hit=terms.find(t=>base.includes(t));if(hit){result[group].push(canon);ev.push(evidence(`Treffer „${hit}“ im CRM-/Website-Kontext.`,hit,c.website_url||"CRM"))}}Object.keys(result).forEach(k=>result[k]=[...new Set(result[k])]);c.tags=result;c.evidence=ev;applyLearn(c);c.crawl_status="success";c.last_crawled_at=new Date().toISOString();c.opportunity_score=score(c);c.priority=priority(c.opportunity_score);c.clusters=matchClusters(c);save();return c}
function stripHtml(h){return String(h||"").replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<[^>]+>/g," ").replace(/&nbsp;/gi," ").replace(/&amp;/gi,"&").replace(/&lt;/gi,"<").replace(/&gt;/gi,">").replace(/\s+/g," ").trim()}
