async function fetchPageText(url){if(!/^https?:\/\//i.test(url||""))return{ok:false,error:"keine http(s)-URL"};const proxy=((state.settings&&state.settings.corsProxy)||"").trim();const target=proxy?proxy+encodeURIComponent(url):url;try{const r=await fetch(target,{redirect:"follow"});if(!r.ok)return{ok:false,error:"HTTP "+r.status};const html=await r.text();return{ok:true,text:stripHtml(html),html:html}}catch(e){return{ok:false,error:e.message||String(e)}}}
function subpageLinks(html,base){let origin,basePath="/",dir="/";try{const bu=new URL(base);origin=bu.origin;basePath=bu.pathname||"/";dir=basePath.replace(/[^/]*$/,"")}catch(e){return[]}const isListing=basePath!=="/"&&dir!=="/";const kw=/impressum|ueber|über|about|kontakt|contact|unternehmen|company|standort|location|karriere|career|jobs|profil|zahlen|facts|presse|press|medien|media|news|aktuell|mitteilung|meldung/i;const out=[],seen={};const re=/href\s*=\s*["']([^"'#]+)["']/gi;let m;while((m=re.exec(html))&&out.length<10){let href=m[1];if(!href||/^(mailto:|tel:|javascript:|data:)/i.test(href))continue;let abs,path;try{const au=new URL(href,base);if(au.origin!==origin)continue;abs=au.href.split("#")[0];path=au.pathname}catch(e){continue}if(seen[abs]||abs===base)continue;const kwHit=kw.test(abs);const child=isListing&&path.indexOf(dir)===0&&path.length>basePath.length;if(kwHit||child){seen[abs]=1;out.push(abs)}}return out}
async function crawlWebsite(u,max,parts,used){const f=await fetchPageText(u);if(!(f.ok&&f.text)){log("WARN","crawl_fetch_failed",{portal:"website",url:u,error:f.error});return}parts.push("### Quelle: Firmen-Website ("+u+")\n"+f.text.slice(0,max));used.push({portal:"website",url:u,chars:f.text.length});log("INFO","crawl_fetch_ok",{portal:"website",url:u,chars:f.text.length});if(!f.html)return;const listing=/presse|press|medien|media|news|aktuell|mitteilung|meldung/i;let budget=10;const l1=subpageLinks(f.html,u).slice(0,6);for(const su of l1){if(budget<=0)break;const sf=await fetchPageText(su);budget--;if(sf.ok&&sf.text){parts.push("### Unterseite: "+su+"\n"+sf.text.slice(0,Math.round(max/2)));used.push({portal:"website:sub",url:su,chars:sf.text.length});log("INFO","crawl_subpage_ok",{url:su,chars:sf.text.length});if(sf.html&&listing.test(su)){const l2=subpageLinks(sf.html,su).slice(0,3);for(const su2 of l2){if(budget<=0)break;const sf2=await fetchPageText(su2);budget--;if(sf2.ok&&sf2.text){parts.push("### Artikel: "+su2+"\n"+sf2.text.slice(0,Math.round(max/2)));used.push({portal:"website:art",url:su2,chars:sf2.text.length});log("INFO","crawl_article_ok",{url:su2,chars:sf2.text.length})}else{log("WARN","crawl_subpage_failed",{url:su2,error:sf2.error})}}}}else{log("WARN","crawl_subpage_failed",{url:su,error:sf.error})}}}
async function gatherSources(c){const portals=((state.settings&&state.settings.crawlPortals)||[]).filter(p=>p.enabled);const max=(state.settings&&state.settings.maxChars)||6000;const parts=[],used=[];for(const p of portals){const u=portalUrl(p,c);if(!u){log("INFO","crawl_skip_portal",{portal:p.id,reason:"keine URL"});continue}if(p.type==="website"){await crawlWebsite(u,max,parts,used);continue}const f=await fetchPageText(u);if(f.ok&&f.text){parts.push("### Quelle: "+p.name+" ("+u+")\n"+f.text.slice(0,max));used.push({portal:p.id,url:u,chars:f.text.length});log("INFO","crawl_fetch_ok",{portal:p.id,url:u,chars:f.text.length})}else{log("WARN","crawl_fetch_failed",{portal:p.id,url:u,error:f.error})}}if(c.source_text&&c.source_text.trim()){parts.push("### Quelle: Manueller Text\n"+stripHtml(c.source_text).slice(0,max));used.push({portal:"manual",chars:c.source_text.length})}return{text:parts.join("\n\n").slice(0,max*4),used}}
function applyAIResult(c,p,fallbackSource){const v=TAG_VOCAB();const pick=(arr,allow)=>Array.isArray(arr)?[...new Set(arr.map(x=>String(x)).filter(x=>allow.includes(x)))]:[];c.tags={manufacturers:pick(p.manufacturers,v.manufacturers),technologies:pick(p.technologies,v.technologies),business_areas:pick(p.business_areas,v.business_areas)};const ev=[];if(Array.isArray(p.evidence))p.evidence.forEach(e=>{if(e&&e.term)ev.push({term:String(e.term).slice(0,80),source_url:String(e.source_url||fallbackSource||"KI").slice(0,300),evidence:String(e.evidence||"").slice(0,240),confidence:Math.max(0,Math.min(1,Number(e.confidence)||0.7))})});if(Array.isArray(p.signals))p.signals.forEach(s=>{const term=typeof s==="string"?s:(s&&s.term);if(term)ev.push({term:String(term).slice(0,80),source_url:fallbackSource||"KI-Signal",evidence:"KI-Signal",confidence:0.6})});c.evidence=ev;if(p.nace_code&&!c.nace_code)c.nace_code=String(p.nace_code).slice(0,12);if(p.nace_label&&!c.nace_label)c.nace_label=String(p.nace_label).slice(0,140);c.ai_summary=p.summary?String(p.summary).slice(0,800):"";c.ai_potential=p.potential?String(p.potential).slice(0,12).toLowerCase():"";const fg=(p.firmographics&&typeof p.firmographics==="object")?p.firmographics:{};c.firmographics={employees:sfx(fg.employees,40),employee_range:sfx(fg.employee_range,60),revenue:sfx(fg.revenue,60),locations:sfx(fg.locations,40),location_countries:Array.isArray(fg.location_countries)?fg.location_countries.map(x=>sfx(x,40)).filter(Boolean).slice(0,25):sfx(fg.location_countries,160),founded_year:sfx(fg.founded_year,10),legal_form:sfx(fg.legal_form,60),hq_city:sfx(fg.hq_city,80),hq_country:sfx(fg.hq_country,60),industry:sfx(fg.industry,120),estimated:!!fg.estimated};if(!c.employee_range&&c.firmographics.employee_range)c.employee_range=c.firmographics.employee_range;if(!c.legal_form&&c.firmographics.legal_form)c.legal_form=c.firmographics.legal_form;if(!c.city&&c.firmographics.hq_city)c.city=c.firmographics.hq_city;if(!c.country&&c.firmographics.hq_country)c.country=c.firmographics.hq_country;if(!c.industry&&c.firmographics.industry)c.industry=c.firmographics.industry;if((!c.crm_revenue||c.crm_revenue===0)&&c.firmographics.revenue){const rv=parseRevenue(c.firmographics.revenue);if(rv>0)c.crm_revenue=rv}}
function localSummary(c){const s=c.opportunity_score,terms=(c.raw_tags||[]),t=tags(c);const lvl=s>=75?"sehr hoch":s>=55?"hoch":s>=35?"mittel":"eher niedrig";const found=t.length?("Gefunden wurden u. a.: "+t.slice(0,8).join(", ")+"."):"Es wurden noch keine belastbaren Signale gefunden.";const base=terms.length?("Bezogen auf die Suchbegriffe „"+terms.join("“, „")+"“ ist das Potenzial "+lvl+" (Score "+s+"/100, Prioritaet "+c.priority+")."):("Das Potenzial ist "+lvl+" (Score "+s+"/100, Prioritaet "+c.priority+"). Es sind keine Suchbegriffe hinterlegt.");return base+" "+found}
function setAIResult(c){state.aiResult={company_id:c.company_id,name:c.company_name,summary:c.ai_summary||localSummary(c),potential:c.ai_potential||(c.opportunity_score>=55?"hoch":c.opportunity_score>=35?"mittel":"niedrig"),score:c.opportunity_score,priority:c.priority,terms:c.raw_tags||[],tags:tags(c),firmographics:c.firmographics||{},stammdaten:buildStammdaten(c),ai:c.ai||{},fit:c.fit||{},change:c.change||{},changeHistory:c.changeHistory||[],profileName:(c.fit&&c.fit.profile)||(activeProfile().name||"")}}
function formatEuro(n){n=Number(n)||0;if(!n)return"";return n.toLocaleString("de-DE")+" €"}
function buildStammdaten(c){const fg=c.firmographics||{};const lc=Array.isArray(fg.location_countries)?fg.location_countries.join(", "):(fg.location_countries||"");return {groesse:fg.employee_range||c.employee_range||"",mitarbeiter:fg.employees||"",umsatz:fg.revenue||(c.crm_revenue?formatEuro(c.crm_revenue):""),niederlassungen:fg.locations||"",laender:lc||fg.hq_country||c.country||"",gruendung:fg.founded_year||"",rechtsform:fg.legal_form||c.legal_form||"",hauptsitz:[fg.hq_city||c.city,fg.hq_country||c.country].filter(Boolean).join(", "),branche:fg.industry||c.industry||"",nace:c.nace_code||"",estimated:!!fg.estimated}}
function activeProfile(){const s=state.settings||{};return (s.profiles&&s.profiles[s.activeProfile])||DEFAULT_PROFILES()["it-distribution"]}
function knownGroup(canon){for(const g of Object.keys(TAG_MAP))if(Object.keys(TAG_MAP[g]).includes(canon))return g;return null}
function learnRules(){const s=state.settings;if(!s.learn||typeof s.learn!=="object")s.learn={guidance:[],termMap:{},negatives:[],positives:[]};const L=s.learn;L.guidance=Array.isArray(L.guidance)?L.guidance:[];L.termMap=(L.termMap&&typeof L.termMap==="object")?L.termMap:{};L.negatives=Array.isArray(L.negatives)?L.negatives:[];L.positives=Array.isArray(L.positives)?L.positives:[];L.pending=Array.isArray(L.pending)?L.pending:[];L.negativeCorpus=Array.isArray(L.negativeCorpus)?L.negativeCorpus:[];return L}
function gateLearn(kind,payload){const L=learnRules();const reasons=[];const stop=["und","der","die","das","gmbh","ag","co","kg","mbh","ohg","the","inc","ltd","und co","www","com"];if(kind==="term"){const from=String(payload.from||"").trim().toLowerCase(),to=String(payload.to||"").trim();if(from.length<3)reasons.push("Begriff zu kurz/unspezifisch (min. 3 Zeichen)");if(stop.includes(from))reasons.push("Begriff ist ein generisches Stichwort");if(!to)reasons.push("Ziel-Tag fehlt");else if(!knownGroup(to))reasons.push("Ziel ist kein bekannter Kanon-Tag");if(L.termMap[from]!=null)reasons.push("Regel bereits vorhanden (Dublette)");(L.negativeCorpus||[]).forEach(nc=>{if(from&&String(nc.text||"").toLowerCase().includes(from)&&(nc.mustNot||[]).some(t=>String(t).toLowerCase()===to.toLowerCase()))reasons.push("Konflikt mit Negativ-Korpus: „"+nc.text+"“")})}else if(kind==="neg"){const tag=String(payload.tag||"").trim();if(!tag)reasons.push("Tag fehlt");else if(!knownGroup(tag))reasons.push("Kein bekannter Kanon-Tag");if(L.negatives.map(x=>x.toLowerCase()).includes(tag.toLowerCase()))reasons.push("Bereits als Fehltreffer vorhanden (Dublette)");(L.positives||[]).forEach(p=>{if((p.tags||[]).some(t=>String(t).toLowerCase()===tag.toLowerCase()))reasons.push("Widerspricht Positivbeispiel „"+(p.name||"")+"“ (senkt Precision)")})}else if(kind==="guide"){const g=String(payload.text||"").trim();if(g.length<8)reasons.push("Regel zu kurz/unspezifisch (min. 8 Zeichen)");if(L.guidance.map(x=>x.toLowerCase()).includes(g.toLowerCase()))reasons.push("Regel bereits vorhanden (Dublette)")}return{ok:reasons.length===0,reasons:reasons}}
function learnBlock(){const L=learnRules();const parts=[];if(L.guidance.length)parts.push("Beruecksichtige diese gelernten Regeln: "+L.guidance.map(x=>"- "+x).join(" "));const tm=Object.keys(L.termMap);if(tm.length)parts.push("Begriffs-Normalisierung: "+tm.map(k=>k+" -> "+L.termMap[k]).join("; "));if(L.negatives.length)parts.push("Diese Signale sind KEINE starken Fit-Indikatoren: "+L.negatives.join(", "));return parts.length?(" "+parts.join(" ")):""}
function applyLearn(c){const L=learnRules();const base=(c.company_name+" "+(c.industry||"")+" "+(c.raw_tags||[]).join(" ")+" "+(c.source_text||"")+" "+(c.website_url||"")).toLowerCase();c.tags=c.tags||{manufacturers:[],technologies:[],business_areas:[]};Object.keys(L.termMap).forEach(raw=>{const canon=L.termMap[raw];const g=knownGroup(canon);if(g&&base.includes(String(raw).toLowerCase())){c.tags[g]=c.tags[g]||[];if(!c.tags[g].includes(canon))c.tags[g].push(canon)}});L.negatives.forEach(neg=>{["manufacturers","technologies","business_areas"].forEach(g=>{c.tags[g]=(c.tags[g]||[]).filter(t=>String(t).toLowerCase()!==String(neg).toLowerCase())})})}
function learnedHtml(){const L=learnRules();const g=L.guidance.map((x,i)=>'<div class="split" style="padding:3px 0"><span>'+esc(x)+'</span><button class="btn danger" data-del-guide="'+i+'">×</button></div>').join("")||'<div class="muted">keine</div>';const tmk=Object.keys(L.termMap);const tm=tmk.map(k=>'<div class="split" style="padding:3px 0"><span>'+esc(k)+' → '+esc(L.termMap[k])+'</span><button class="btn danger" data-del-term="'+esc(k)+'">×</button></div>').join("")||'<div class="muted">keine</div>';const ng=L.negatives.map((x,i)=>'<div class="split" style="padding:3px 0"><span>'+esc(x)+'</span><button class="btn danger" data-del-neg="'+i+'">×</button></div>').join("")||'<div class="muted">keine</div>';const ps=L.positives.map((x,i)=>'<div class="split" style="padding:3px 0"><span>'+esc(x.name||"")+' '+badge((x.band||"?")+"-Account")+'</span><button class="btn danger" data-del-pos="'+i+'">×</button></div>').join("")||'<div class="muted">keine</div>';const pd=L.pending.map((it,i)=>'<div class="list-item"><b>'+esc(it.kind)+'</b> '+esc(JSON.stringify(it.rule))+'<div class="muted">Gate: '+esc((it.reasons||[]).join("; "))+'</div><div class="toolbar" style="margin-top:4px"><button class="btn" data-act-pending="'+i+'">Trotzdem aktivieren</button><button class="btn danger" data-disc-pending="'+i+'">Verwerfen</button></div></div>').join("")||'<div class="muted">keine</div>';const nc=L.negativeCorpus.map((x,i)=>'<div class="split" style="padding:3px 0"><span>'+esc(x.text)+' <span class="muted">≠ '+esc((x.mustNot||[]).join(", "))+'</span></span><button class="btn danger" data-del-nc="'+i+'">×</button></div>').join("")||'<div class="muted">keine</div>';return '<div class="panel"><h3>Gelerntes (global)</h3><div style="margin-top:6px"><small class="muted">Regeln/Hinweise</small>'+g+'</div><div style="margin-top:6px"><small class="muted">Begriffs-Normalisierung</small>'+tm+'</div><div style="margin-top:6px"><small class="muted">Fehltreffer-Signale</small>'+ng+'</div><div style="margin-top:6px"><small class="muted">Positivbeispiele</small>'+ps+'</div><div style="margin-top:10px;border-top:1px solid var(--line);padding-top:8px"><h4 style="margin:0 0 6px">Qualitäts-Gate: wartet auf Freigabe</h4>'+pd+'</div><div style="margin-top:8px"><small class="muted">Negativ-Korpus (Gegenbeispiele: Text ≠ Tags)</small>'+nc+'<div class="toolbar" style="margin-top:6px"><input id="ncText" class="search" placeholder="Beispieltext"><input id="ncTags" class="search" placeholder="darf NICHT taggen: Tag1, Tag2"><button class="btn" data-add-nc>Gegenbeispiel hinzufügen</button></div></div></div>'}
function statusBadge(s){s=String(s||"").toLowerCase();let c="gray-b",t=s||"nicht bekannt";if(s.includes("nachgewiesen"))c="green-b";else if(s.includes("wahrscheinlich"))c="blue-b";else if(s.includes("pruef")||s.includes("prüf"))c="amber-b";return '<span class="badge '+c+'">'+esc(t)+'</span>'}
function ampelBadge(v){v=String(v||"").toLowerCase();let c="gray-b";if(v==="ja")c="green-b";else if(v==="teilweise")c="amber-b";else if(v==="nein")c="red-b";return '<span class="badge '+c+'">'+esc(v||"unbekannt")+'</span>'}
function localSub(c,key){if(key==="usecases")return Math.min(1,tags(c).length/5);return Math.max(0,Math.min(1,(score(c)||0)/100))}
function computeFit(c){const prof=activeProfile();const crit=(Array.isArray(prof.scoreCriteria)&&prof.scoreCriteria.length)?prof.scoreCriteria:[{key:"usecases",label:"Use Cases",weight:100}];let tot=0,wsum=0;const rows=crit.map(cr=>{const has=c.ai&&c.ai.subscores&&typeof c.ai.subscores[cr.key]==="number";const sub=has?c.ai.subscores[cr.key]:null;const eff=sub==null?localSub(c,cr.key):sub;tot+=eff*cr.weight;wsum+=cr.weight;return{label:cr.label,weight:cr.weight,sub:sub}});const sc=wsum?Math.round(tot*100/wsum):0;const b=prof.bands||{A:75,B:55,C:35};const band=sc>=b.A?"A":sc>=b.B?"B":sc>=b.C?"C":"D";c.fit={score:sc,band:band,criteria:rows,profile:prof.name||prof.id};c.opportunity_score=sc;c.priority=band;return c.fit}
function oppCfg(){return Object.assign(DEFAULT_OPP(),(state.settings&&state.settings.opp)||{})}
function ageFactor(dateStr){const cfg=oppCfg();const t=Date.parse((dateStr||"")+((dateStr||"").length<=7?"-15":""));if(isNaN(t))return .6;const days=Math.max(0,(Date.now()-t)/864e5);for(const[lim,f]of cfg.decay)if(days<=lim)return f;return .1}
function kindBadge(k){const m={FACT:["Fakt","#16794322","#0f7a3d"],INFERENCE:["Ableitung","#1f6feb22","#1f6feb"],HYPOTHESIS:["Hypothese","#b4690e22","#b4690e"]};const x=m[k]||m.INFERENCE;return '<span class="badge" style="background:'+x[1]+';color:'+x[2]+'">'+x[0]+'</span>'}
function kindWeight(k){return k==="FACT"?1:k==="INFERENCE"?.7:.4}
function computeChange(c){const cfg=oppCfg();const sigs=(c.ai&&Array.isArray(c.ai.signals))?c.ai.signals:[];let changeRaw=0,mpsRaw=0,mpsMax=0,confAcc=0,confW=0;const present={};sigs.forEach(s=>{const w=cfg.weights[s.type]||0;const af=ageFactor(s.date);const kw=kindWeight(s.kind);const eff=w*af*kw;changeRaw+=eff;if(cfg.mps[s.type]){mpsRaw+=eff;mpsMax+=w}present[s.type]=Math.max(present[s.type]||0,af);confAcc+=kw*af;confW++});const comboNotes=[];(cfg.combos||[]).forEach(cb=>{if((cb.all||[]).every(t=>present[t]!=null)){changeRaw+=cb.bonus;mpsRaw+=cb.bonus;comboNotes.push(cb.note)}});const changeScore=Math.min(100,Math.round(changeRaw));const mps=mpsMax?Math.min(100,Math.round(mpsRaw*100/mpsMax)):0;const fit=(c.fit&&typeof c.fit.score==="number")?c.fit.score:(c.opportunity_score||0);const opportunity=Math.round(.6*mps+.4*fit);const confidence=sigs.length?Math.round(100*confAcc/confW):0;c.change={changeScore:changeScore,opportunity:opportunity,mps:mps,confidence:confidence,signals:sigs.length,comboNotes:comboNotes};if(!Array.isArray(c.changeHistory))c.changeHistory=[];c.changeHistory.push({d:new Date().toISOString().slice(0,10),change:changeScore,opp:opportunity});if(c.changeHistory.length>30)c.changeHistory=c.changeHistory.slice(-30);return c.change}
function changeHtml(a){const ch=a.change||{};const sigs=(a.ai&&Array.isArray(a.ai.signals))?a.ai.signals:[];if(!ch.signals&&!sigs.length)return'<div style="margin-top:14px;border-top:1px solid var(--line);padding-top:10px"><small class="muted">Veränderungs-Signale: keine belegten Veränderungen gefunden. Aktiviere Job-/News-Portale unter „Quellen & Crawling" oder hinterlege aktuellen Quelltext.</small></div>';const kpi=(l,v)=>'<div style="text-align:center;min-width:96px"><div style="font-size:22px;font-weight:700">'+v+'</div><div class="muted" style="font-size:11px">'+l+'</div></div>';const rows=sigs.map(s=>'<div class="list-item"><b>'+esc((s.type||"").replace(/_/g," "))+'</b> '+kindBadge(s.kind)+(s.date?' <span class="muted">'+esc(s.date)+' · Alter-Faktor '+ageFactor(s.date).toFixed(2)+'</span>':'')+(s.evidence?'<div class="muted">'+esc(s.evidence)+'</div>':'')+(s.source_url?'<div><a href="'+esc(s.source_url)+'" target="_blank" rel="noopener">Quelle</a></div>':'')+'</div>').join("");const combos=(ch.comboNotes&&ch.comboNotes.length)?'<div style="margin-top:6px"><small class="muted">Signal-Kombinationen:</small><ul style="margin:4px 0 0 18px">'+ch.comboNotes.map(n=>'<li>'+esc(n)+'</li>').join("")+'</ul></div>':'';return '<div style="margin-top:14px;border-top:1px solid var(--line);padding-top:10px"><h4 style="margin:0 0 8px">Veränderungs- & Opportunity-Analyse</h4><div class="split" style="justify-content:space-around;flex-wrap:wrap;gap:8px;margin-bottom:8px">'+kpi("Change",ch.changeScore||0)+kpi("MPS-Opportunity",ch.opportunity||0)+kpi("Confidence",(ch.confidence||0)+"%")+'</div><small class="muted">Erkannte Veränderungen ('+sigs.length+'):</small>'+rows+combos+'</div>'}
function applyAIExtras(c,p){const S=x=>String(x==null?"":x);const st=x=>{x=S(x).toLowerCase();return x.includes("nachgewiesen")?"nachgewiesen":x.includes("wahrscheinlich")?"wahrscheinlich relevant":(x.includes("pruef")||x.includes("prüf"))?"zu pruefen":"nicht bekannt"};const ai={};ai.role=S(p.supply_chain_role).slice(0,60);ai.useCases=Array.isArray(p.use_cases)?p.use_cases.slice(0,12).map(u=>({name:S(u&&u.name).slice(0,90),evidence:S(u&&u.evidence).slice(0,240),status:st(u&&u.status)})).filter(u=>u.name):[];ai.buyingCenter=Array.isArray(p.buying_center)?p.buying_center.slice(0,12).map(b=>({rolle:S(b&&b.rolle).slice(0,60),interesse:S(b&&b.interesse).slice(0,140)})).filter(b=>b.rolle):[];ai.dimensions={};if(p.dimensions&&typeof p.dimensions==="object")Object.keys(p.dimensions).slice(0,20).forEach(k=>{const val=S(p.dimensions[k]).toLowerCase();ai.dimensions[String(k).slice(0,60)]=["ja","teilweise","nein"].includes(val)?val:"unbekannt"});ai.compliance=Array.isArray(p.compliance)?p.compliance.slice(0,20).map(x=>({thema:S(x&&x.thema).slice(0,80),status:st(x&&x.status)})).filter(x=>x.thema):[];ai.subscores={};if(p.subscores&&typeof p.subscores==="object")Object.keys(p.subscores).forEach(k=>{const n=Number(p.subscores[k]);if(!isNaN(n))ai.subscores[String(k).slice(0,40)]=Math.max(0,Math.min(1,n>1?n/100:n))});const bl=p.summary_blocks||{};const arr=x=>Array.isArray(x)?x.slice(0,8).map(y=>(y&&typeof y==="object")?{text:S(y.text).slice(0,220),url:S(y.url||y.source_url).slice(0,240)}:{text:S(y).slice(0,220),url:""}).filter(o=>o.text):[];ai.blocks={fakten:arr(bl.fakten),hypothesen:arr(bl.hypothesen),pruefpunkte:arr(bl.pruefpunkte),unbekannt:arr(bl.unbekannt)};const allowed=Object.keys((state.settings.opp||DEFAULT_OPP()).weights);ai.signals=Array.isArray(p.change_signals)?p.change_signals.slice(0,20).map(s=>{const t=S(s&&s.type).toUpperCase().replace(/[^A-Z_]/g,"");const k=S(s&&s.kind).toUpperCase();return{type:t,date:S(s&&s.date).slice(0,10),evidence:S(s&&s.evidence).slice(0,240),source_url:S(s&&s.source_url).slice(0,240),kind:["FACT","INFERENCE","HYPOTHESIS"].includes(k)?k:"INFERENCE"}}).filter(s=>allowed.includes(s.type)):[];c.ai=ai}
function aiSectionsHtml(ai,fit){ai=ai||{};fit=fit||{};const parts=[];if(Array.isArray(fit.criteria)&&fit.criteria.length){parts.push('<div style="margin-top:10px"><small class="muted">Fit-Score-Treiber:</small>'+fit.criteria.map(cr=>'<div class="split" style="border-bottom:1px solid var(--line);padding:4px 0"><span>'+esc(cr.label)+' <span class="muted">('+cr.weight+')</span></span><b>'+(cr.sub==null?'<span class="muted">– (Heuristik)</span>':Math.round(cr.sub*100)+'%')+'</b></div>').join("")+'</div>')}if(ai.role)parts.push('<div style="margin-top:8px"><small class="muted">Supply-Chain-Rolle:</small> <b>'+esc(ai.role)+'</b></div>');if(Array.isArray(ai.useCases)&&ai.useCases.length)parts.push('<div style="margin-top:8px"><small class="muted">Use Cases:</small>'+ai.useCases.map(u=>'<div class="list-item"><b>'+esc(u.name)+'</b> '+statusBadge(u.status)+(u.evidence?'<div class="muted">'+esc(u.evidence)+'</div>':'')+'</div>').join("")+'</div>');if(ai.dimensions&&Object.keys(ai.dimensions).length)parts.push('<div style="margin-top:8px"><small class="muted">Readiness:</small><div class="grid grid-2">'+Object.keys(ai.dimensions).map(k=>'<div class="split" style="padding:3px 0"><span>'+esc(k)+'</span>'+ampelBadge(ai.dimensions[k])+'</div>').join("")+'</div></div>');if(Array.isArray(ai.buyingCenter)&&ai.buyingCenter.length)parts.push('<div style="margin-top:8px"><small class="muted">Buying Center:</small>'+ai.buyingCenter.map(b=>'<div class="split" style="padding:3px 0"><span><b>'+esc(b.rolle)+'</b></span><span class="muted">'+esc(b.interesse)+'</span></div>').join("")+'</div>');if(Array.isArray(ai.compliance)&&ai.compliance.length)parts.push('<div style="margin-top:8px"><small class="muted">Compliance:</small>'+ai.compliance.map(x=>'<div class="split" style="padding:3px 0"><span>'+esc(x.thema)+'</span>'+statusBadge(x.status)+'</div>').join("")+'</div>');const b=ai.blocks||{};const blk=(t,a)=>Array.isArray(a)&&a.length?'<div style="margin-top:6px"><small class="muted">'+t+':</small><ul style="margin:4px 0 0 18px">'+a.map(x=>{const o=(x&&typeof x==="object")?x:{text:String(x),url:""};return '<li>'+esc(o.text)+(o.url&&/^https?:\/\//i.test(o.url)?' <a href="'+esc(o.url)+'" target="_blank" rel="noopener" title="Quelle öffnen">↗ Beleg</a>':'')+'</li>'}).join("")+'</ul></div>':'';const blocks=blk("Fakten",b.fakten)+blk("Hypothesen",b.hypothesen)+blk("Pruefpunkte",b.pruefpunkte)+blk("Nicht bekannt",b.unbekannt);if(blocks)parts.push('<div style="margin-top:8px">'+blocks+'</div>');return parts.join("")}
function profileView(){const s=state.settings;const ids=Object.keys(s.profiles);const p=activeProfile();const lines=a=>Array.isArray(a)?a.join("\n"):"";const crit=(p.scoreCriteria||[]).map((cr,i)=>'<div class="split" style="padding:4px 0"><span>'+esc(cr.label)+' <span class="muted">('+esc(cr.key)+')</span></span><input type="number" min="0" max="100" data-crit="'+i+'" value="'+Number(cr.weight||0)+'" style="width:80px"></div>').join("");return page("Vertriebs-Profil","Persona, Leitfrage, Use Cases, Bewertungsdimensionen und Score-Gewichte – steuert die KI-Analyse global",`<div class="panel"><div class="toolbar"><label>Aktives Profil <select id="profSel">${ids.map(id=>`<option value="${esc(id)}" ${id===s.activeProfile?"selected":""}>${esc(s.profiles[id].name||id)}</option>`).join("")}</select></label><button class="btn primary" data-action="switchProfile">Umschalten</button> <input id="pfNew" placeholder="Name für neues Profil" style="min-width:200px"><button class="btn" data-action="addProfile">+ Neues Profil</button><button class="btn danger" data-action="delProfile">Profil löschen</button></div><div class="form-grid"><label class="full">Profilname<input id="pfName" value="${esc(p.name||"")}"></label><label class="full">Persona<textarea id="pfPersona">${esc(p.persona||"")}</textarea></label><label class="full">Leitfrage<textarea id="pfLeit">${esc(p.leitfrage||"")}</textarea></label><label>Use-Case-Kategorien (eine pro Zeile)<textarea id="pfUse">${esc(lines(p.useCases))}</textarea></label><label>Readiness-Dimensionen (eine pro Zeile)<textarea id="pfDim">${esc(lines(p.dimensions))}</textarea></label><label>Compliance-Themen (eine pro Zeile)<textarea id="pfComp">${esc(lines(p.compliance))}</textarea></label><label>Buying-Center-Rollen (eine pro Zeile)<textarea id="pfRoles">${esc(lines(p.buyingRoles))}</textarea></label></div><h3>Score-Gewichte</h3>${crit}<div class="toolbar" style="margin-top:8px"><label>A ab <input type="number" id="pfBandA" value="${Number((p.bands||{}).A||75)}" style="width:80px"></label><label>B ab <input type="number" id="pfBandB" value="${Number((p.bands||{}).B||55)}" style="width:80px"></label><label>C ab <input type="number" id="pfBandC" value="${Number((p.bands||{}).C||35)}" style="width:80px"></label></div><div style="margin-top:12px"><h4 style="margin:0 0 6px">Zielbranchen (für Firmensuche)</h4><div class="grid grid-2">${((state.settings.akquise&&state.settings.akquise.branchen)||[]).map(b=>'<label style="display:flex;gap:6px;align-items:center"><input type="checkbox" data-pbranch="'+esc(b.id)+'" '+(((p.branchen||[]).indexOf(b.id)>=0)?"checked":"")+'>'+esc(b.name)+'</label>').join("")}</div><p class="muted">Nutzt Implisense (falls aktiv), sonst die KI; Treffer landen im Reiter Akquise.</p><div class="toolbar" style="margin-top:8px"><button class="btn" data-action="profilSuche">Nach gewählten Branchen suchen</button></div></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" data-action="saveProfile">Profil speichern</button></div><p class="muted">Die Gewichte müssen nicht exakt 100 ergeben – der Score wird normalisiert. Das aktive Profil steuert KI-Prompt, erkannte Use Cases, Readiness-Dimensionen, Compliance-Themen und den gewichteten Fit-Score.</p></div>${learnedHtml()}`)}
function stammdatenHtml(sd){if(!sd)return"";const rows=[["Unternehmensgröße",sd.groesse],["Mitarbeiterzahl",sd.mitarbeiter],["Jahresumsatz",sd.umsatz],["Niederlassungen",sd.niederlassungen],["Länder",sd.laender],["Hauptsitz",sd.hauptsitz],["Rechtsform",sd.rechtsform],["Gründungsjahr",sd.gruendung],["Branche",sd.branche],["NACE",sd.nace]];const known=[sd.groesse,sd.mitarbeiter,sd.umsatz,sd.niederlassungen].some(Boolean);const body=rows.map(r=>'<div class="split" style="border-bottom:1px solid var(--line);padding:5px 0"><span class="muted">'+esc(r[0])+'</span><b>'+(r[1]?esc(r[1]):'<span class="muted">unbekannt</span>')+'</b></div>').join("");const hint=known?"":'<p class="muted" style="margin-top:6px">Noch keine Unternehmensdaten gewonnen. Pruefe die Azure-Verbindung (HTTP 401?) oder hinterlege einen Website-/Quelltext bzw. aktiviere ein Crawling-Portal.</p>';return '<div style="margin-top:14px"><h4 style="margin:0 0 6px">Gewonnene Stammdaten'+((sd.estimated&&known)?' <span class="muted" style="font-weight:400">(geschätzt)</span>':'')+'</h4><div class="grid grid-2">'+body+'</div>'+hint+'</div>'}
function sfx(v,n){return v==null?"":String(v).slice(0,n||120)}
function parseRevenue(s){if(s==null)return 0;if(typeof s==="number")return s;let t=String(s).toLowerCase().replace(/[.\s]/g,"").replace(/,/g,".");const m=t.match(/([0-9]+(?:\.[0-9]+)?)/);if(!m)return 0;let n=parseFloat(m[1]);if(/mrd|milliard|bn|billion/.test(t))n*=1e9;else if(/mio|million/.test(t)||/[0-9]m(?![a-z])/.test(t))n*=1e6;else if(/tsd|tausend/.test(t)||/[0-9]k(?![a-z])/.test(t))n*=1e3;return Math.round(n)}
function fgHtml(fg){if(!fg)return"";const rows=[["Mitarbeiterzahl",fg.employees],["Unternehmensgröße",fg.employee_range],["Jahresumsatz",fg.revenue],["Niederlassungen",fg.locations],["Gründungsjahr",fg.founded_year],["Rechtsform",fg.legal_form],["Hauptsitz",[fg.hq_city,fg.hq_country].filter(Boolean).join(", ")],["Branche",fg.industry]].filter(r=>r[1]);if(!rows.length)return"";return '<div style="margin-top:10px"><small class="muted">Firmographics (Vertrieb):</small><div class="grid grid-2" style="margin-top:6px">'+rows.map(r=>'<div class="split" style="border-bottom:1px solid var(--line);padding:4px 0"><span class="muted">'+esc(r[0])+'</span><b>'+esc(r[1])+'</b></div>').join("")+'</div></div>'}
async function analyzeCompanyAI(c){const a=state.azure;if(!a.endpoint||!a.deployment||!a.apiKey)throw new Error("Azure nicht konfiguriert");const src=await gatherSources(c);const v=TAG_VOCAB();const prof=activeProfile();const critList=(prof.scoreCriteria||[]).map(x=>x.key+" ("+x.label+", Gewicht "+x.weight+")").join("; ");const sys=prof.persona+" Leitfrage: "+prof.leitfrage+" Gehe vor: Unternehmen verstehen, Supply-Chain-Rolle einordnen, Probleme ableiten, Use Cases finden, Business Case bewerten, Anforderungen/Compliance pruefen, Score bilden, Buying Center bestimmen. Trenne konsequent Fakten, Hypothesen, Pruefpunkte und Unbekanntes. Erfinde nichts (keine Zertifizierungen/Zulassungen); kennzeichne Unsicherheit. Antworte AUSSCHLIESSLICH mit einem JSON-Objekt nach dem Schema {\"manufacturers\":[],\"technologies\":[],\"business_areas\":[],\"nace_code\":\"\",\"nace_label\":\"\",\"supply_chain_role\":\"\",\"use_cases\":[{\"name\":\"\",\"evidence\":\"\",\"status\":\"nachgewiesen|wahrscheinlich relevant|zu pruefen|nicht bekannt\"}],\"buying_center\":[{\"rolle\":\"\",\"interesse\":\"\"}],\"dimensions\":{},\"compliance\":[{\"thema\":\"\",\"status\":\"nachgewiesen|wahrscheinlich relevant|zu pruefen|nicht bekannt\"}],\"subscores\":{},\"evidence\":[{\"term\":\"\",\"source_url\":\"\",\"evidence\":\"\",\"confidence\":0.0}],\"firmographics\":{\"employees\":\"\",\"employee_range\":\"\",\"revenue\":\"\",\"locations\":\"\",\"location_countries\":[],\"founded_year\":\"\",\"legal_form\":\"\",\"hq_city\":\"\",\"hq_country\":\"\",\"industry\":\"\",\"estimated\":false},\"potential\":\"hoch|mittel|niedrig\",\"summary\":\"\",\"summary_blocks\":{\"fakten\":[{\"text\":\"\",\"url\":\"\"}],\"hypothesen\":[{\"text\":\"\",\"url\":\"\"}],\"pruefpunkte\":[{\"text\":\"\",\"url\":\"\"}],\"unbekannt\":[]},\"change_signals\":[{\"type\":\"\",\"date\":\"\",\"evidence\":\"\",\"source_url\":\"\",\"kind\":\"FACT|INFERENCE|HYPOTHESIS\"}]}. manufacturers/technologies/business_areas nur aus den erlaubten Listen. use_cases nur aus den erlaubten Use-Case-Kategorien, jede mit kurzem Beleg und Status. dimensions: fuer jede Readiness-Dimension einen Wert ja|teilweise|nein|unbekannt. compliance: fuer jedes relevante Thema einen Status. subscores: fuer jeden Score-Schluessel eine Zahl zwischen 0 und 1. firmographics: fuelle Mitarbeiter, Umsatz, Standorte/Laender, Rechtsform, Hauptsitz, Branche und Gruendungsjahr. Nutze zuerst den Quelltext; wenn kein Quelltext vorliegt, das Unternehmen dir aber allgemein bekannt ist (z. B. grosses/bekanntes Unternehmen), fuelle die bekannten Werte aus deinem Wissen und setze estimated=true. Nur wenn wirklich unbekannt, Feld leer lassen. potential: genau hoch, mittel oder niedrig. summary: 2-4 Saetze umgangssprachlich zum Potenzial bezogen auf die Suchbegriffe. summary_blocks: JEDER Eintrag in fakten/hypothesen/pruefpunkte ist ein Objekt {text,url}; url MUSS die konkrete Quelle sein, aus der die Aussage stammt (Deep-Link zur Unterseite/Meldung aus dem gelieferten Quelltext, z. B. die Pressemitteilung zum neuen Standort), niemals eine erfundene URL. Liegt fuer eine Aussage keine belegbare Quelle vor, gehoert sie nicht in fakten. change_signals: nur tatsaechlich im Quelltext belegte Veraenderungen (Wachstum, neue Standorte, Umzug, neue Fuehrungskraefte, Zukauf/Fusion, Investitionen, Restrukturierung, Stellenaufbau); type NUR aus der erlaubten Signalliste; date=Meldungsdatum (YYYY-MM oder YYYY-MM-DD, sonst leer); evidence=kurzer Beleg; source_url=Fundstelle; kind=FACT fuer belegte Fakten, INFERENCE fuer Ableitungen, HYPOTHESIS fuer Vermutungen. Erfinde keine Signale; wenn nichts belegt ist, leere Liste."+learnBlock();const usr="Erlaubte Use-Case-Kategorien: "+(prof.useCases||[]).join(" | ")+"\nReadiness-Dimensionen: "+(prof.dimensions||[]).join(" | ")+"\nCompliance-Themen: "+(prof.compliance||[]).join(" | ")+"\nMoegliche Buying-Center-Rollen: "+(prof.buyingRoles||[]).join(" | ")+"\nScore-Schluessel fuer subscores: "+critList+"\nErlaubte Change-Signal-Typen: "+Object.keys(state.settings.opp.weights).join(", ")+"\nErlaubte Hersteller: "+v.manufacturers.join(", ")+"\nErlaubte Technologien: "+v.technologies.join(", ")+"\nErlaubte Geschaeftsfelder: "+v.business_areas.join(", ")+"\n\nFirmendaten:\nName: "+(c.company_name||"")+"\nBranche: "+(c.industry||"")+"\nOrt: "+(c.city||"")+" "+(c.country||"")+"\nBekannte Firmendaten: Mitarbeiterklasse "+(c.employee_range||"?")+", Umsatz "+(c.crm_revenue||"?")+"\nCRM-Suchbegriffe: "+((c.raw_tags||[]).join(", "))+"\nWebsite: "+(c.website_url||"")+"\n\nRecherchierter Quelltext:\n"+(src.text||"(kein externer Text verfuegbar - nur die CRM-Felder nutzen)");const out=await azureChat([{role:"system",content:sys},{role:"user",content:usr}],{maxTokens:4000,jsonMode:true});const parsed=extractJson(out);if(!parsed){log("ERROR","ai_json_unparseable",{company:c.company_id,chars:(out||"").length,snippet:String(out||"").slice(0,200)});throw new Error("KI-Antwort nicht als JSON lesbar (Länge "+((out||"").length)+")")}applyAIResult(c,parsed,(src.used[0]&&src.used[0].url)||c.website_url||"KI");applyAIExtras(c,parsed);applyLearn(c);c.crawl_status="success";c.last_crawled_at=new Date().toISOString();computeFit(c);computeChange(c);c.clusters=matchClusters(c);setAIResult(c);save();log("INFO","ai_analysis_ok",{company:c.company_id,sources:src.used.length,fit:c.fit.score,band:c.fit.band,profile:state.settings.activeProfile});return{sources:src.used}}
function matchClusters(c){const ts=new Set(tags(c));return CLUSTERS.filter(x=>x.all.every(t=>ts.has(t))&&(x.any.length===0||x.any.some(t=>ts.has(t)))).map(x=>x.name)}
function importSample(){fetch("data/sample_companies.json").then(r=>r.json()).then(rows=>{state.companies=rows.map(normalizeCompany);save();render();toast("Beispieldaten geladen")}).catch(()=>toast("Beispieldaten konnten bei file:// nicht geladen werden. JSON-Import verwenden."))}
function page(title,sub,body,actions=""){return `<section class="main"><div class="page-head"><div><h2>${title}</h2><div class="muted">${sub}</div></div><div class="toolbar">${actions}</div></div>${body}</section>`}
function dashboard(){const cs=state.companies, crawled=cs.filter(c=>c.crawl_status==="success").length, avg=cs.length?Math.round(cs.reduce((a,c)=>a+c.opportunity_score,0)/cs.length):0;return page("Dashboard","Übersicht über CRM-Anreicherung, Tags und Vertriebschancen",`<div class="grid grid-4"><div class="card kpi">CRM-Unternehmen<b>${cs.length}</b><small>importiert / erfasst</small></div><div class="card kpi">Crawls erfolgreich<b>${crawled}</b><small>von ${cs.length}</small></div><div class="card kpi">Ø Opportunity Score<b>${avg}</b><small>von 100</small></div><div class="card kpi">CRM Cluster<b>${CLUSTERS.length}</b><small>regelbasiert aktiv</small></div></div><div class="grid grid-2" style="margin-top:14px"><div class="panel"><div class="split"><h3>Top-Tags</h3><button class="btn green" data-action="crawlAll">Alle crawlen</button></div>${allTags().slice(0,12).map(([t,n])=>`<div style="margin:12px 0"><div class="split"><span>${esc(t)}</span><b>${n}</b></div><div class="bar"><i style="width:${cs.length?Math.round(n/cs.length*100):0}%"></i></div></div>`).join("")||'<div class="empty">Noch keine Tags vorhanden.</div>'}</div><div class="panel"><h3>Prioritäten</h3>${["A","B","C","D"].map(p=>{const n=cs.filter(c=>c.priority===p).length;return `<div class="split" style="padding:13px 0;border-bottom:1px solid var(--line)">${badge(p)}<b>${n} Unternehmen</b></div>`}).join("")}</div></div>`)}
function hasAI(c){return !!(c.ai_summary||(c.fit&&c.fit.score!=null)||(c.ai&&Object.keys(c.ai).length))}
function aiViewObj(c){return {company_id:c.company_id,name:c.company_name,profileName:(c.fit&&c.fit.profile)||(activeProfile().name||""),potential:c.ai_potential||"",score:(c.fit&&c.fit.score!=null)?c.fit.score:c.opportunity_score,priority:(c.fit&&c.fit.band)||c.priority,fit:c.fit||{},summary:c.ai_summary||localSummary(c),terms:c.raw_tags||[],tags:tags(c),ai:c.ai||{},stammdaten:buildStammdaten(c),change:c.change||{},changeHistory:c.changeHistory||[]}}
function aiInlineCell(c){const a=aiViewObj(c);return `<div class="panel" style="margin:6px 0"><div class="split"><b>KI-Auswertung: ${esc(a.name)}</b><button class="btn" data-ai-collapse="${esc(c.company_id)}">Einklappen ▴</button></div><div class="toolbar" style="margin:6px 0"><button class="btn primary" data-ai="${esc(c.company_id)}">KI-Analyse aktualisieren</button>${c.last_crawled_at?`<span class="muted">Stand: ${esc(c.last_crawled_at)}</span>`:""}</div>${analysisInner(a)}</div>`}
function companies(){const q=(document.querySelector("#companySearch")?.value||"").toLowerCase();const rows=state.companies.filter(c=>(c.company_name+" "+c.company_id+" "+c.industry+" "+tags(c).join(" ")).toLowerCase().includes(q));return page("Unternehmen","CRM-Stammdaten bearbeiten, analysieren und crawlen",`<div class="toolbar"><input id="companySearch" class="search" placeholder="Unternehmen, Branche oder Tag suchen" value="${esc(q)}" oninput="render()"><select id="priorityFilter" onchange="render()"><option value="">Alle Prioritäten</option>${["A","B","C","D"].map(x=>`<option ${document.querySelector("#priorityFilter")?.value===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="panel table-wrap" style="margin-top:14px"><table class="table"><tr><th>Unternehmen</th><th>Branche / NACE</th><th>Tags</th><th>Score</th><th>Priorität</th><th>Status</th><th>Aktionen</th></tr>${rows.filter(c=>{const f=document.querySelector("#priorityFilter")?.value;return !f||c.priority===f}).map(c=>`<tr><td><b>${esc(c.company_name)}</b><div class="muted">${esc(c.company_id)} · ${esc(c.city)}</div></td><td>${esc(c.industry)}<div class="muted">${esc(c.nace_code)}</div></td><td>${tags(c).slice(0,7).map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</td><td><b>${c.opportunity_score}</b></td><td>${badge(c.priority)}</td><td>${badge(c.crawl_status)}</td><td><div class="toolbar"><button class="btn primary" data-ai="${esc(c.company_id)}">KI-Analyse</button>${hasAI(c)?`<button class="btn" data-ai-toggle="${esc(c.company_id)}">${expandedAI===c.company_id?"▴":"▾"} Auswertung</button>`:""}<button class="btn green" data-crawl="${esc(c.company_id)}">Crawlen</button><button class="btn" data-edit="${esc(c.company_id)}">Bearbeiten</button><button class="btn danger" data-delete="${esc(c.company_id)}">Löschen</button></div></td></tr>${expandedAI===c.company_id?`<tr class="ai-row"><td colspan="7">${aiInlineCell(c)}</td></tr>`:""}`).join("")||'<tr><td colspan="7" class="empty">Keine Unternehmen gefunden.</td></tr>'}</table></div>`,"<button class=\"btn\" data-action=\"crawlAllAI\">KI: Alle analysieren</button><button class=\"btn\" data-action=\"exportCsv\">Export CSV</button><button class=\"btn\" data-action=\"exportJsonl\">Export JSONL</button><button class=\"btn primary\" data-action=\"add\">+ Unternehmen hinzufügen</button>")}
function raw(){return page("Raw Data Explorer","Unveränderte CRM- und Crawl-Felder bleiben nachvollziehbar erhalten",`<div class="panel table-wrap"><table class="table"><tr><th>ID</th><th>Firmenname</th><th>Website</th><th>Rechtsform</th><th>Branche</th><th>NACE</th><th>Mitarbeiter</th><th>Ort</th><th>Raw Tags</th><th>Crawl</th><th>Aktualisiert</th></tr>${state.companies.map(c=>`<tr><td>${esc(c.company_id)}</td><td>${esc(c.company_name)}</td><td>${esc(c.website_url)}</td><td>${esc(c.legal_form)}</td><td>${esc(c.industry)}</td><td>${esc(c.nace_code)}</td><td>${esc(c.employee_range)}</td><td>${esc(c.city)}</td><td>${esc(c.raw_tags.join(" | "))}</td><td>${badge(c.crawl_status)}</td><td>${esc(c.last_crawled_at)}</td></tr>`).join("")}</table></div>`)}
function tagsView(){const pairs=allTags();return page("Tag Explorer","Normalisierte Hersteller-, Technologie- und Geschäftsfeld-Tags",`<div class="grid grid-3">${Object.entries(TAG_MAP).map(([g,map])=>`<div class="panel"><h3>${g==="manufacturers"?"Hersteller":g==="technologies"?"Technologien":"Geschäftsfelder"}</h3>${Object.keys(map).map(t=>{const n=state.companies.filter(c=>c.tags[g].includes(t)).length;return `<div class="split" style="padding:8px 0;border-bottom:1px solid var(--line)"><span>${esc(t)}</span><b>${n}</b></div>`}).join("")}</div>`).join("")}</div><div class="panel" style="margin-top:14px"><h3>Evidence-Treffer</h3>${state.companies.flatMap(c=>c.evidence.map(e=>`<div class="list-item"><b>${esc(c.company_name)} · ${esc(e.term)}</b><div>${esc(e.evidence)}</div><small class="muted">${esc(e.source_url)} · Confidence ${Math.round(e.confidence*100)}%</small></div>`)).join("")||'<div class="empty">Noch keine Evidence vorhanden.</div>'}</div>`)}
function clusters(){return page("CRM Cluster","Automatisch berechnete Zielgruppen für Kampagnen und CRM-Segmente",`<div class="grid grid-2">${CLUSTERS.map(cl=>{const members=state.companies.filter(c=>matchClusters(c).includes(cl.name));return `<div class="panel"><div class="split"><h3>${esc(cl.name)}</h3>${badge(members.length+" Treffer")}</div><p class="muted">Kriterien: ${[...cl.all,...cl.any].join(" · ")||"keine"}</p>${members.map(c=>`<div class="list-item"><b>${esc(c.company_name)}</b><div>${tags(c).map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</div></div>`).join("")||'<div class="empty">Keine passenden Unternehmen. Tags ergänzen oder crawlen.</div>'}</div>`}).join("")}</div>`,"<button class=\"btn green\" data-action=\"exportClusters\">Cluster exportieren</button>")}
function sales(){const rows=[...state.companies].sort((a,b)=>b.opportunity_score-a.opportunity_score);return page("Sales Intelligence","Vertriebspriorisierung auf Basis von CRM-Daten und Enrichment",`<div class="panel table-wrap"><table class="table"><tr><th>Unternehmen</th><th>Opportunity Score</th><th>Priorität</th><th>Umsatz</th><th>Empfehlung</th><th>Cluster</th></tr>${rows.map(c=>`<tr><td><b>${esc(c.company_name)}</b><div class="muted">${esc(c.industry)}</div></td><td><span class="score">${c.opportunity_score}</span>/100</td><td>${badge(c.priority)}</td><td>${Number(c.crm_revenue||0).toLocaleString("de-DE")} €</td><td>${esc(c.priority==="A"?"Account-Review und Kampagne priorisieren":c.priority==="B"?"Gezielte Herstellerkampagne vorbereiten":"Daten ergänzen und qualifizieren")}</td><td>${c.clusters.map(x=>`<span class="tag">${esc(x)}</span>`).join("")||"–"}</td></tr>`).join("")}</table></div>`)}
function tender(){const rows=state.companies.map(c=>({company_id:c.company_id,company_name:c.company_name,capabilities:[...c.tags.business_areas,...c.tags.technologies],tender_categories:c.tags.business_areas,signals:c.evidence.map(e=>e.term),embedding_ready_text:`${c.company_name}. ${c.industry}. ${tags(c).join(", ")}.`}));return page("Tender AI Context","Separater Kontext für semantische Suche und Tender-Matching",`<div class="panel"><p class="muted">Der Tender-Kontext wird getrennt vom Sales-Ergebnis exportiert. API-Schlüssel werden nicht exportiert.</p><div class="code">${esc(JSON.stringify(rows.slice(0,2),null,2))}</div></div>`,"<button class=\"btn green\" data-action=\"exportTender\">JSONL exportieren</button>")}
function azure(){const a=state.azure;const u=buildAzureUrl(a);return page("Azure AI Setup","Azure OpenAI-Verbindung für bidirektionale Analysen",`<div class="panel"><div class="alert warn"><b>Wichtig:</b> Der Endpoint darf nur der Ressourcen-Host sein. Die Anwendung verwendet ausschließlich den unten angezeigten URL-Builder.</div><div class="form-grid"><label>Azure OpenAI Endpoint<input id="azEndpoint" value="${esc(a.endpoint)}" placeholder="https://name.openai.azure.com"></label><label>Deployment-Name<input id="azDeployment" value="${esc(a.deployment)}" placeholder="GPT-Deployment"></label><label>API-Version<select id="azVersion"><option ${a.apiVersion==="2025-04-01-preview"?"selected":""}>2025-04-01-preview</option><option ${a.apiVersion==="2024-10-21"?"selected":""}>2024-10-21</option><option ${a.apiVersion==="2024-08-01-preview"?"selected":""}>2024-08-01-preview</option></select></label><label>API-Schlüssel<input id="azKey" type="password" value="${esc(a.apiKey)}" placeholder="Azure OpenAI API-Key"></label></div><div class="toolbar" style="margin-top:14px"><button class="btn" data-action="saveAzure">Speichern</button><button class="btn primary" data-action="testAzure">Verbindung testen</button><button class="btn" data-action="downloadLog">Logfile herunterladen</button>${badge(a.status.state==="ok"?"Azure verbunden":a.status.state==="error"?"Azure Fehler":"Nicht getestet")}</div><div class="alert ${a.status.state==="ok"?"ok":a.status.state==="error"?"err":"warn"}">${esc(a.status.message||"Noch kein Verbindungstest ausgeführt.")}</div><h3>Effektive Request-URL</h3><div class="code">${esc(u)}</div><p class="muted">Bei direktem Öffnen über file:// kann Azure den Browseraufruf wegen CORS blockieren. Ein solcher Fehler wird separat geloggt. Die URL darf aber niemals doppelt aufgebaut werden.</p></div>`)}
function sources(){const s=state.settings;const rows=s.crawlPortals.map((p,i)=>`<tr><td style="text-align:center"><input type="checkbox" data-portal-enabled="${i}" ${p.enabled?"checked":""}></td><td><input class="search" data-portal-name="${i}" value="${esc(p.name)}"></td><td>${p.type==="website"?'<span class="muted">nutzt Firmen-Website</span>':`<input class="search" style="min-width:340px" data-portal-url="${i}" value="${esc(p.url)}">`}</td><td>${badge(p.type)}</td><td><button class="btn danger" data-portal-del="${i}" ${p.id==="website"?"disabled":""}>Entfernen</button></td></tr>`).join("");return page("Quellen & Crawling","Global festlegen, welche Portale gecrawlt werden – gilt für alle Unternehmen und neue Ausschreibungen",`<div class="panel"><div class="alert warn">Platzhalter in URL-Vorlagen: <b>{q}</b> = Firmenname, <b>{domain}</b> = Website-Domain. Typ <b>website</b> nutzt direkt die hinterlegte Unternehmens-Website.</div><div class="table-wrap"><table class="table"><tr><th>Aktiv</th><th>Portal</th><th>URL-Vorlage</th><th>Typ</th><th></th></tr>${rows}</table></div><div class="toolbar" style="margin-top:12px"><button class="btn" data-action="addPortal">+ Portal hinzufügen</button><button class="btn primary" data-action="saveSources">Speichern</button></div></div><div class="panel"><h3>CORS-Proxy (optional)</h3><div class="form-grid"><label class="full">Proxy-Präfix für Crawling<input id="setProxy" value="${esc(s.corsProxy||"")}" placeholder="https://mein-proxy/?url="></label></div><p class="muted">Direkte Website-Aufrufe aus <code>file://</code> blockiert der Browser meist per CORS. Zwei Auswege: den Browser mit <code>--disable-web-security</code> starten (siehe README) oder hier ein Proxy-Präfix hinterlegen, an das die Ziel-URL angehängt wird. Der Proxy sieht die gecrawlten URLs – nur vertrauenswürdige Proxys nutzen.</p><div class="toolbar"><button class="btn primary" data-action="saveSources">Speichern</button></div></div>${akqImplisensePanel()}`)}
function diagnostics(){return page("Diagnose & Tests","Lokale Unit Tests und optionaler echter Azure-Live-Test",`<div class="toolbar"><button class="btn primary" data-action="runTests">Unit Tests ausführen</button><button class="btn" data-action="runAzureTest">Tests + Azure Live-Test</button><button class="btn" data-action="downloadLog">Logfile herunterladen</button><button class="btn danger" data-action="clearLog">Log löschen</button></div><div id="testResults" class="panel" style="margin-top:14px">${state.testResults||'<div class="empty">Noch keine Tests ausgeführt.</div>'}</div><div class="panel"><h3>Log</h3><div class="code">${esc(logLines.join("\n")||"Noch keine Logeinträge.")}</div></div>`)}
function buildAzureUrl(raw){let ep=String(raw?.endpoint||"").trim();if(!ep)return"";if(!/^https?:\/\//i.test(ep))ep="https://"+ep;let base;try{base=new URL(ep).origin}catch(e){base=ep.replace(/\/openai\/.*$/i,"").replace(/[?#].*$/,"").replace(/\/+$/,"")}let dep=String(raw?.deployment||"").trim().replace(/^.*\/deployments\//i,"").split("/")[0];let ver=String(raw?.apiVersion||"").trim();if(!/^\d{4}-\d{2}-\d{2}(?:-preview)?$/.test(ver))ver="2025-04-01-preview";return dep?`${base}/openai/deployments/${encodeURIComponent(dep)}/chat/completions?api-version=${encodeURIComponent(ver)}`:""}
function validateAzureUrl(url){const e=[];if((url.match(/\/openai\/deployments\//g)||[]).length!==1)e.push("Deployment-Pfad muss genau einmal vorkommen");if((url.match(/\/chat\/completions/g)||[]).length!==1)e.push("Chat-Completion-Pfad muss genau einmal vorkommen");if(url.includes("/openai/responses"))e.push("Responses-Pfad ist nicht zulässig");if(/chat\/completions[^?#]*\/openai\//i.test(url))e.push("Nach chat/completions folgt ein weiterer Azure-Pfad");if(e.length)throw new Error(e.join("; "));return true}
function log(level,event,data={}){const safe=Object.assign({},data);delete safe.apiKey;delete safe.key;delete safe.apikey;delete safe["api-key"];const line=new Date().toISOString()+" ["+level+"] "+event+" "+JSON.stringify(safe);logLines.push(line);if(logLines.length>500)logLines.shift();saveLog();return line}
async function azureChat(messages,{maxTokens=800,temperature=0,jsonMode=false}={}){const a=state.azure,url=buildAzureUrl(a);if(!url)throw new Error("Azure-Konfiguration unvollständig");validateAzureUrl(url);log("INFO","azure_request_prepared",{url,jsonMode});let useCompletionTokens=false,dropTemp=false,dropJson=false;for(let attempt=0;attempt<5;attempt++){const body={messages};if(useCompletionTokens)body.max_completion_tokens=maxTokens;else body.max_tokens=maxTokens;if(!dropTemp&&temperature!=null)body.temperature=temperature;if(jsonMode&&!dropJson)body.response_format={type:"json_object"};let r;try{r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","api-key":a.apiKey},body:JSON.stringify(body)})}catch(e){log("ERROR","azure_connection_failed",Object.assign({message:e.message||String(e)},azureCtx()));throw new Error("Netzwerk-/CORS-Fehler: "+(e.message||e))}const text=await r.text();if(r.ok){let content="";try{const j=JSON.parse(text);content=(j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content)||""}catch(e){content=text}log("INFO","azure_connection_succeeded",{status:r.status,url,chars:content.length,params:{tokenParam:useCompletionTokens?"max_completion_tokens":"max_tokens",temperature:dropTemp?"default":temperature}});return content}const d=text.toLowerCase();if(r.status===400){if(!useCompletionTokens&&/max_tokens/.test(d)&&(/max_completion_tokens/.test(d)||/not supported|unsupported/.test(d))){log("INFO","azure_retry_max_completion_tokens",{});useCompletionTokens=true;continue}if(useCompletionTokens&&/max_completion_tokens/.test(d)&&/not supported|unsupported|unknown|unrecognized/.test(d)){useCompletionTokens=false;continue}if(!dropTemp&&/temperature/.test(d)&&/not support|unsupported|does not support|only.*(default|1)/.test(d)){log("INFO","azure_retry_drop_temperature",{});dropTemp=true;continue}if(jsonMode&&!dropJson&&/response_format|json_object|json mode/.test(d)&&/not support|unsupported|does not support|unknown|unrecognized|invalid|cannot/.test(d)){log("INFO","azure_retry_drop_response_format",{});dropJson=true;continue}}log("ERROR","azure_http_error",Object.assign({status:r.status,detail:text.slice(0,300),attempt:attempt+1,tokenParam:useCompletionTokens?"max_completion_tokens":"max_tokens"},azureCtx()));const hint=r.status===401?" — API-Schlüssel bzw. Endpoint/Region prüfen (der Schlüssel muss zur Azure-Ressource des Endpoints gehören)":r.status===404?" — Deployment-Name prüfen":r.status===400?" — Parameter/API-Version prüfen":"";throw new Error(`Azure HTTP ${r.status}: ${text.slice(0,300)}${hint}`)}log("ERROR","azure_fallback_exhausted",{url});throw new Error("Azure-Anfrage schlägt auch nach Parameter-Fallback fehl.")}
async function testAzure(){const a=state.azure;if(!a.endpoint||!a.deployment||!a.apiKey){a.status={state:"error",message:"Endpoint, Deployment-Name und API-Schlüssel sind erforderlich."};save();render();return}try{const out=await azureChat([{role:"system",content:"Antworte ausschließlich mit OK."},{role:"user",content:"Verbindungstest"}]);a.status={state:"ok",message:"Azure AI verbunden. Antwort: "+out.slice(0,100)};log("INFO","azure_test_ok",{})}catch(e){a.status={state:"error",message:e.message};log("ERROR","azure_test_failed",{message:e.message,url:buildAzureUrl(a)});}save();render()}
function formCompany(c={}){const x=normalizeCompany(c);return `<div class="modal-box"><div class="modal-head"><h2>${c.company_id?"Unternehmen bearbeiten":"Unternehmen hinzufügen"}</h2><button class="btn" data-close>×</button></div><div class="form-grid"><label>Company ID<input id="f_id" value="${esc(x.company_id)}"></label><label>Firmenname<input id="f_name" value="${esc(x.company_name)}"></label><label>Website<input id="f_url" value="${esc(x.website_url)}"></label><label>Rechtsform<input id="f_legal" value="${esc(x.legal_form)}"></label><label>Branche<input id="f_industry" value="${esc(x.industry)}"></label><label>NACE-Code<input id="f_nace" value="${esc(x.nace_code)}"></label><label>NACE-Bezeichnung<input id="f_nacelabel" value="${esc(x.nace_label)}"></label><label>Mitarbeiterklasse<input id="f_emp" value="${esc(x.employee_range)}"></label><label>Ort<input id="f_city" value="${esc(x.city)}"></label><label>Land<input id="f_country" value="${esc(x.country)}"></label><label>CRM-Umsatz<input id="f_rev" type="number" value="${Number(x.crm_revenue||0)}"></label><label>Mitarbeiterzahl<input id="f_emps" value="${esc((x.firmographics||{}).employees||"")}"></label><label>Niederlassungen<input id="f_locs" value="${esc((x.firmographics||{}).locations||"")}"></label><label>Gründungsjahr<input id="f_founded" value="${esc((x.firmographics||{}).founded_year||"")}"></label><label>Priorität<select id="f_prio">${["A","B","C","D"].map(p=>`<option ${x.priority===p?"selected":""}>${p}</option>`).join("")}</select></label><label class="full">Tags / Suchbegriffe (Komma getrennt)<input id="f_tags" value="${esc(x.raw_tags.join(", "))}"></label><label class="full">Website-/Quelltext für KI (optional)<textarea id="f_srctext" placeholder="Text von der Website hier einfügen, falls automatisches Crawling per CORS blockiert wird">${esc(x.source_text)}</textarea></label><label class="full">Notizen<textarea id="f_notes">${esc(x.notes)}</textarea></label></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" data-save-company="${esc(x.company_id)}">Speichern</button><button class="btn" data-close>Abbrechen</button></div></div>`}
function openCompany(id=""){const c=id?state.companies.find(x=>x.company_id===id):{};const m=document.querySelector("#modal");m.innerHTML=formCompany(c);m.classList.remove("hidden");m.querySelectorAll("[data-close]").forEach(x=>x.onclick=closeModal);m.querySelector("[data-save-company]").onclick=()=>saveCompany(id);bind()}
function analysisInner(a){return `<div style="margin:10px 0">${badge("Profil: "+(a.profileName||"—"))} ${badge("Potenzial: "+a.potential)} <b>Fit-Score ${a.score}/100</b> · ${badge(((a.fit&&a.fit.band)||a.priority)+"-Account")}</div><p style="line-height:1.5">${esc(a.summary)}</p>${aiSectionsHtml(a.ai,a.fit)}${changeHtml(a)}<div style="margin-top:8px"><small class="muted">Ausgewertete Suchbegriffe:</small><br>${(a.terms||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join("")||'<span class="muted">keine hinterlegt</span>'}</div>${(a.tags&&a.tags.length)?`<div style="margin-top:8px"><small class="muted">Erkannte Tags:</small><br>${a.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</div>`:""}${stammdatenHtml(a.stammdaten)}<div style="margin-top:14px;border-top:1px solid var(--line);padding-top:10px"><small class="muted">Lernen (wirkt global auf alle & neue Unternehmen):</small><div class="toolbar" style="margin-top:6px"><input id="learnGuide" class="search" placeholder="Regel/Hinweis, z. B. reine Handelsfirmen niedriger werten"><button class="btn" data-learn-guide>Regel lernen</button><button class="btn green" data-learn-pos="${esc(a.company_id)}">Als Positivbeispiel</button></div><div class="toolbar" style="margin-top:6px"><input id="learnFrom" class="search" placeholder="Begriff (Rohtext)"><input id="learnTo" class="search" placeholder="Kanon-Tag"><button class="btn" data-learn-term>Normalisierung lernen</button><input id="learnNeg" class="search" placeholder="Fehltreffer-Tag"><button class="btn danger" data-learn-neg>Als Fehltreffer</button></div></div>`}
function openAnalysis(id){const c=state.companies.find(x=>x.company_id===id);if(!c)return;setAIResult(c);const a=state.aiResult;const m=document.querySelector("#modal");m.innerHTML=`<div class="modal-box"><div class="modal-head"><h2>KI-Auswertung: ${esc(a.name)}</h2><button class="btn" data-close>×</button></div>${analysisInner(a)}</div>`;m.classList.remove("hidden");m.querySelectorAll("[data-close]").forEach(x=>x.onclick=closeModal);bind()}
function analysisSection(c){const has=!!(c.ai_summary||(c.fit&&c.fit.score!=null)||(c.ai&&Object.keys(c.ai).length));const a={company_id:c.company_id,name:c.company_name,profileName:(c.fit&&c.fit.profile)||(activeProfile().name||""),potential:c.ai_potential||"",score:(c.fit&&c.fit.score!=null)?c.fit.score:c.opportunity_score,priority:(c.fit&&c.fit.band)||c.priority,fit:c.fit||{},summary:c.ai_summary||localSummary(c),terms:c.raw_tags||[],tags:tags(c),ai:c.ai||{},stammdaten:buildStammdaten(c)};return `<details class="ai-details" ${has?"open":""} style="margin-top:14px;border:1px solid var(--line);border-radius:8px;padding:10px"><summary style="cursor:pointer;font-weight:600">KI-Auswertung${has?` — Fit ${a.score}/100 · ${esc(a.priority)}-Account`:" (noch keine – jetzt starten)"}</summary><div class="toolbar" style="margin:8px 0"><button class="btn primary" data-ai-refresh="${esc(c.company_id)}">KI-Analyse ${has?"aktualisieren":"starten"}</button>${c.last_crawled_at?`<span class="muted">Stand: ${esc(c.last_crawled_at)}</span>`:""}</div>${has?analysisInner(a):'<div class="muted">Noch keine Analyse für dieses Unternehmen.</div>'}</details>`}
function saveCompany(oldId){const v=id=>document.querySelector("#"+id)?.value||"";const c=normalizeCompany({company_id:v("f_id").trim()||"CRM-"+Date.now(),company_name:v("f_name").trim()||"Unbenannt",website_url:v("f_url").trim(),legal_form:v("f_legal").trim(),industry:v("f_industry").trim(),nace_code:v("f_nace").trim(),nace_label:v("f_nacelabel").trim(),employee_range:v("f_emp").trim(),city:v("f_city").trim(),country:v("f_country").trim(),crm_revenue:Number(v("f_rev"))||0,priority:v("f_prio"),raw_tags:v("f_tags").split(",").map(x=>x.trim()).filter(Boolean),notes:v("f_notes"),source_text:v("f_srctext")});const i=state.companies.findIndex(x=>x.company_id===oldId);const base=i>=0?(state.companies[i].firmographics||{}):{};c.firmographics=Object.assign({},base,{employees:v("f_emps").trim(),locations:v("f_locs").trim(),founded_year:v("f_founded").trim()});if(i>=0){c.tags=state.companies[i].tags;c.evidence=state.companies[i].evidence;c.crawl_status=state.companies[i].crawl_status;c.opportunity_score=state.companies[i].opportunity_score;c.clusters=state.companies[i].clusters;c.ai_summary=state.companies[i].ai_summary;c.ai_potential=state.companies[i].ai_potential;state.companies[i]=c}else state.companies.push(c);save();closeModal();render();toast("Unternehmen gespeichert")}
function closeModal(){document.querySelector("#modal").classList.add("hidden")}
function exportFile(name,content,type="application/json"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function importData(file){const reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result);if(!Array.isArray(data))data=data.companies||[];state.companies=data.map(normalizeCompany);save();render();toast("Daten importiert")}catch(e){toast("Importfehler: "+e.message)}};reader.readAsText(file)}
function csv(rows){return rows.map(r=>r.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(";")).join("\n")}
function exportClusters(){const rows=[["cluster_id","cluster_name","company_id","company_name","matched_tags"]];CLUSTERS.forEach(cl=>state.companies.filter(c=>matchClusters(c).includes(cl.name)).forEach(c=>rows.push([cl.id,cl.name,c.company_id,c.company_name,tags(c).join("|")])));exportFile("crm_clusters.csv",csv(rows),"text/csv")}
function exportTender(){const rows=state.companies.map(c=>JSON.stringify({company_id:c.company_id,company_name:c.company_name,capability_profile:[...c.tags.business_areas,...c.tags.technologies],tender_categories:c.tags.business_areas,relevance_signals:c.evidence.map(e=>e.term),embedding_ready_text:`${c.company_name}. ${c.industry}. ${tags(c).join(", ")}.`})).join("\n");exportFile("tender_ai_context.jsonl",rows,"application/x-ndjson")}
function backup(){const x=JSON.parse(JSON.stringify(state));x.azure.apiKey="";exportFile("also-crm-backup.json",JSON.stringify(x,null,2))}
function exportAnalysisCSV(){const head=["company_id","company_name","website","branche","nace","unternehmensgroesse","mitarbeiter","umsatz","niederlassungen","laender","hauptsitz","rechtsform","gruendung","supply_chain_role","fit_score","fit_band","prioritaet","potenzial","use_cases","buying_center","compliance","tags","suchbegriffe","summary","stand"];const rows=[head];state.companies.forEach(c=>{const sd=buildStammdaten(c);const ai=c.ai||{},fit=c.fit||{};const uc=(ai.useCases||[]).map(u=>u.name+" ["+u.status+"]").join("; ");const bc=(ai.buyingCenter||[]).map(b=>b.rolle+(b.interesse?" ("+b.interesse+")":"")).join("; ");const comp=(ai.compliance||[]).map(x=>x.thema+" ["+x.status+"]").join("; ");rows.push([c.company_id,c.company_name,c.website_url,sd.branche,c.nace_code,sd.groesse,sd.mitarbeiter,sd.umsatz,sd.niederlassungen,sd.laender,sd.hauptsitz,sd.rechtsform,sd.gruendung,ai.role||"",(fit.score!=null?fit.score:c.opportunity_score),fit.band||c.priority,c.priority,c.ai_potential||"",uc,bc,comp,tags(c).join("; "),(c.raw_tags||[]).join("; "),c.ai_summary||"",c.last_crawled_at||""])});exportFile("crm_analyse_"+new Date().toISOString().slice(0,10)+".csv",csv(rows),"text/csv");log("INFO","export_csv",{companies:state.companies.length})}
function exportAnalysisJSONL(){const prof=activeProfile();const rows=state.companies.map(c=>{const sd=buildStammdaten(c);const ai=c.ai||{},fit=c.fit||{};return JSON.stringify({company_id:c.company_id,company_name:c.company_name,website:c.website_url,profil:prof.name,supply_chain_role:ai.role||"",fit_score:(fit.score!=null?fit.score:c.opportunity_score),fit_band:fit.band||c.priority,potenzial:c.ai_potential||"",stammdaten:sd,tags:tags(c),use_cases:ai.useCases||[],buying_center:ai.buyingCenter||[],readiness:ai.dimensions||{},compliance:ai.compliance||[],evidence:c.evidence||[],summary:c.ai_summary||"",summary_blocks:ai.blocks||{},last_crawled_at:c.last_crawled_at||""})}).join("\n");exportFile("crm_analyse_"+new Date().toISOString().slice(0,10)+".jsonl",rows,"application/x-ndjson");log("INFO","export_jsonl",{companies:state.companies.length})}
function runTests(live=false){const results=[];function t(name,fn){try{fn();results.push({name,ok:true,msg:"OK"})}catch(e){results.push({name,ok:false,msg:e.message})}}t("URL normalisiert",()=>{const u=buildAzureUrl({endpoint:"https://x.openai.azure.com/openai/responses?api-version=bad",deployment:"D",apiVersion:"0205-04-01-preview"});if(u!=="https://x.openai.azure.com/openai/deployments/D/chat/completions?api-version=2025-04-01-preview")throw Error(u)});t("URL nicht doppelt",()=>{const u=buildAzureUrl({endpoint:"https://x.openai.azure.com/openai/deployments/D/chat/completions?api-version=2025-04-01-preview",deployment:"D",apiVersion:"2025-04-01-preview"});validateAzureUrl(u)});t("Crawling erzeugt Tags",()=>{const c=normalizeCompany({company_name:"Test Microsoft Azure",raw_tags:[]});crawlCompany(c);if(!tags(c).length)throw Error("Keine Tags")});t("Cluster berechenbar",()=>{const c=normalizeCompany({company_name:"Test",tags:{manufacturers:["Microsoft"],technologies:["Azure"],business_areas:["Cloud Services"]}});if(!matchClusters(c).length)throw Error("Kein Cluster")});t("Log schützt Schlüssel",()=>{const before=logLines.length;log("INFO","secret_test",{apiKey:"DO_NOT_LOG"});if(logLines.slice(before).join("").includes("DO_NOT_LOG"))throw Error("API-Key geloggt")});if(live){return (async()=>{try{await testAzure();results.push({name:"Azure Live-Verbindung",ok:state.azure.status.state==="ok",msg:state.azure.status.message})}catch(e){results.push({name:"Azure Live-Verbindung",ok:false,msg:e.message})}showTests(results)})()}showTests(results)}
function showTests(rs){state.testResults=rs.map(r=>`<div class="list-item">${r.ok?"✅":"❌"} <b>${esc(r.name)}</b><div class="muted">${esc(r.msg)}</div></div>`).join("");log("INFO","unit_tests_completed",{passed:rs.filter(x=>x.ok).length,failed:rs.filter(x=>!x.ok).length});render()}
/* ===== Akquise & Implisense (portiert in die CRM-Data-App) =====
   Vermarktung von Tender AI: Marktanbieter je Branche, Kontakte,
   Priorisierung, Outlook-Export, KI-E-Mails je Phase mit Antwort-Auswertung,
   Nachfass-Fristen, Dubletten, Signatur, A/B-Erstansprache mit Lernen,
   Opt-out/Blacklist, Implisense-Connector (v2). Global in state.settings.akquise. */
function akqDefaults(){return{
 branchen:[
  {id:'br-it-daas',name:'IT-Arbeitsplatz / Device-as-a-Service',passt:'Geräteflotte, Rollout/Rollback, SLA, Flottenmanagement, EVB-IT: fast 1:1',anpassen:'Katalogspalten, Mengenfelder',geeignet:true,aktiv:true},
  {id:'br-medtech',name:'Medizin- und Labortechnik',passt:'Gerätepark, Wartung, Teststellung, Verbrauchsmaterial, Finanzierung',anpassen:'MDR und Hygiene nicht abgebildet',geeignet:true,aktiv:true},
  {id:'br-itservice',name:'IT-Services, Systemhäuser, Managed Services',passt:'Service, SLA, Ticketsystem, IT-Sicherheit und Authentifizierung sind schon Felder',anpassen:'Gerätefelder überwiegend überflüssig',geeignet:true,aktiv:true},
  {id:'br-automaten',name:'Kaffee-/Verkaufsautomaten, Wasserspender',passt:'Gleiches Modell wie MPS: Gerät, Verbrauch, Service, Abrechnung nach Menge',anpassen:'Katalog, Zählereinheit statt „Klick"',geeignet:true,aktiv:true},
  {id:'br-tk',name:'Telekommunikation und Netzwerktechnik',passt:'Rahmenverträge, Laufzeit, Lose, SLA',anpassen:'Tarif- und Leitungsfelder fehlen',geeignet:true,aktiv:true},
  {id:'br-sicherheit',name:'Sicherheits- und Gebäudetechnik (mit Wartung)',passt:'Standorte, Servicezeiten, Wartung, Reaktionszeiten',anpassen:'Technische Leistungsverzeichnisse',geeignet:true,aktiv:true},
  {id:'br-fuhrpark',name:'Fuhrpark und E-Mobilität',passt:'Laufzeit, Finanzierung, Rücknahme, Service',anpassen:'Fahrzeugkatalog',geeignet:true,aktiv:true},
  {id:'br-bau',name:'Bau (VOB/GAEB)',passt:'—',anpassen:'GAEB-Positionslisten werden nicht strukturiert eingelesen',geeignet:false,aktiv:false},
  {id:'br-beratung',name:'Reine Beratungsleistungen',passt:'—',anpassen:'Fachmodell läuft größtenteils ins Leere',geeignet:false,aktiv:false}
 ],
 firmen:[],
 phasen:['Erstansprache','Nutzen / Follow-up','Terminvorschlag','Lead-Qualifizierung'],
 produkt:'Tender AI — KI-gestützte Analyse öffentlicher Ausschreibungen: liest Vergabeunterlagen, extrahiert Fristen, Anforderungen und Lose, prüft die Eignung, erzeugt Bieterfragen und Konzeptbausteine. Läuft lokal und datensicher.',
 absender:{name:'',firma:'',signatur:'',ton:'professionell, prägnant, wertschätzend, auf Deutsch, kein Marketing-Sprech'},
 emailLearn:[],
 firstTouch:{variants:[]},
 blacklist:[],
 implisense:{enabled:false,baseUrl:'https://api.implisense.com/v2',apiKey:'',authHeader:'Authorization',authPrefix:'Bearer ',searchMethod:'POST',searchBody:'{"query":"{q}","size":15}',searchBranchBody:'{"filter":{"industry":"{q}"},"size":50}',searchPath:'/search',companyPath:'/companies/{id}',eventsPath:'/companies/{id}/changes',status:''}
}}
function akqStore(){state.settings.akquise=state.settings.akquise||akqDefaults();var a=state.settings.akquise,d=akqDefaults();a.branchen=a.branchen||d.branchen;a.firmen=a.firmen||[];a.phasen=a.phasen||d.phasen;a.produkt=a.produkt||d.produkt;a.absender=a.absender||d.absender;a.emailLearn=a.emailLearn||[];a.firstTouch=a.firstTouch||{variants:[]};a.firstTouch.variants=a.firstTouch.variants||[];a.blacklist=a.blacklist||[];if(!a.implisense||typeof a.implisense!=="object")a.implisense={};var di=d.implisense;for(var k in di){if(a.implisense[k]===undefined)a.implisense[k]=di[k]}return a}
function akqUi(){return (window.__akqUi=window.__akqUi||{branche:'',firma:null})}
function akqId(p){return (p||'ak')+'-'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function akqFirma(id){return akqStore().firmen.find(f=>f.id===id)||null}
function akqKontakt(f,kid){return (f&&(f.kontakte||[]).find(k=>k.id===kid))||null}
function akqPrioRank(p){return p==='A'?0:p==='B'?1:p==='C'?2:3}
function akqConfirm(t){return confirm(t+' löschen?')}
function akqAzureReady(){var a=state.azure||{};if(!a.endpoint||!a.deployment||!a.apiKey)return{ok:false,reason:'Azure nicht konfiguriert (Azure AI Setup)'};return{ok:true}}
function akqParseJson(t){if(!t)return null;var s=String(t).replace(/```json/gi,'```').replace(/```/g,'').trim();try{return JSON.parse(s)}catch(_){}var m=s.match(/\[[\s\S]*\]/)||s.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0])}catch(_){}}return null}
function akqToday(){return new Date().toISOString().slice(0,10)}
function akqAppendSig(t){var s=String((akqStore().absender.signatur||'')).trim();t=String(t||'');if(s&&t.indexOf(s)<0)return t.replace(/\s+$/,'')+'\n\n'+s;return t}

/* Branchen */
function akqBrancheAdd(){akqStore().branchen.push({id:akqId('br'),name:'Neue Branche',passt:'',anpassen:'',geeignet:true,aktiv:true});save();render()}
function akqBrancheSet(id,f,v){var b=akqStore().branchen.find(x=>x.id===id);if(b){b[f]=v;save()}}
function akqBrancheToggle(id,f){var b=akqStore().branchen.find(x=>x.id===id);if(b){b[f]=!b[f];save();render()}}
function akqBrancheDel(id){if(!akqConfirm('Diese Branche'))return;var a=akqStore();a.branchen=a.branchen.filter(x=>x.id!==id);save();render()}
function akqBrancheName(bid){var b=akqStore().branchen.find(x=>x.id===bid);return b?b.name:''}
function akqBranchePasst(bid){var b=akqStore().branchen.find(x=>x.id===bid);return b?(b.passt||''):''}

/* Firmen */
function akqFirmaAdd(){var a=akqStore(),u=akqUi();var br=u.branche||(a.branchen.find(b=>b.aktiv)||{}).id||'';a.firmen.push({id:akqId('fi'),branchenId:br,name:'Neuer Marktanbieter',website:'',ort:'',prio:'B',flags:[],notiz:'',quelle:'',kontakte:[],createdAt:new Date().toISOString()});save();render()}
function akqFirmaSet(id,f,v){var o=akqFirma(id);if(o){o[f]=v;save()}}
function akqFirmaDel(id){if(!akqConfirm('Diesen Marktanbieter samt Kontakten'))return;var a=akqStore();a.firmen=a.firmen.filter(x=>x.id!==id);save();render()}
function akqFirmaFlag(id,flag){var f=akqFirma(id);if(!f)return;f.flags=f.flags||[];var i=f.flags.indexOf(flag);if(i<0)f.flags.push(flag);else f.flags.splice(i,1);save();render()}
function akqFirmaOpen(id){var u=akqUi();u.firma=(u.firma===id)?null:id;render()}
function akqFirmaOpen2(id){var u=akqUi();u.firma=id;u.branche='';render()}
function akqFirmaToggleOpt(id){var f=akqFirma(id);if(!f)return;f.optOut=!f.optOut;save();render();toast(f.optOut?'Firma auf „nicht kontaktieren" gesetzt.':'Firma wieder kontaktierbar.')}
function akqUiBranche(v){akqUi().branche=v;render()}
function akqProdSet(f,v){akqStore()[f]=v;save()}
function akqAbsSet(f,v){akqStore().absender[f]=v;save()}

/* Kontakte */
function akqKontaktAdd(fid){var f=akqFirma(fid);if(!f)return;f.kontakte=f.kontakte||[];f.kontakte.push({id:akqId('ko'),name:'',rolle:'',email:'',tel:'',linkedin:'',quelle:'',notiz:'',prio:false});save();render()}
function akqKontaktSet(fid,kid,f,v){var k=akqKontakt(akqFirma(fid),kid);if(k){k[f]=v;save()}}
function akqKontaktDel(fid,kid){if(!akqConfirm('Diesen Kontakt'))return;var f=akqFirma(fid);if(!f)return;f.kontakte=(f.kontakte||[]).filter(x=>x.id!==kid);save();render()}
function akqKontaktPrio(fid,kid){var k=akqKontakt(akqFirma(fid),kid);if(k){k.prio=!k.prio;save();render()}}
function akqKontaktToggleOpt(fid,kid){var k=akqKontakt(akqFirma(fid),kid);if(k){k.optOut=!k.optOut;save();render()}}
function akqMailSet(fid,kid,f,v){var k=akqKontakt(akqFirma(fid),kid);if(k){k.mail=k.mail||{};k.mail[f]=v;save()}}
function akqSetPhase(fid,kid,v){var k=akqKontakt(akqFirma(fid),kid);if(k){k.mail=k.mail||{};k.mail.phase=v;save()}}

function akqSearchLinks(f){var g='https://www.google.com/search?q='+encodeURIComponent((f.name||'')+' Vertriebsleitung');var li='https://www.linkedin.com/search/results/people/?keywords='+encodeURIComponent((f.name||'')+' Vertrieb');var dom='';try{dom=(f.website||'').replace(/^https?:\/\//i,'').replace(/\/.*$/,'')}catch(_){}var imp=dom?('https://www.google.com/search?q='+encodeURIComponent('site:'+dom+' impressum OR kontakt OR vertrieb')):'';return '<a href="'+esc(g)+'" target="_blank" rel="noopener">Websuche</a> · <a href="'+esc(li)+'" target="_blank" rel="noopener">LinkedIn</a>'+(imp?(' · <a href="'+esc(imp)+'" target="_blank" rel="noopener">Impressum/Kontakt</a>'):'')}

/* Opt-out / Blacklist */
function akqBlocked(f,k){if(f&&f.optOut)return 'Firma ist auf „nicht kontaktieren" gesetzt';if(k&&k.optOut)return 'Kontakt hat Opt-out';var bl=akqStore().blacklist||[];var em=String(k&&k.email||'').toLowerCase().trim();var dom='';try{dom=String(f&&f.website||'').replace(/^https?:\/\//i,'').replace(/\/.*$/,'').toLowerCase()}catch(_){}for(var i=0;i<bl.length;i++){var b=String(bl[i]||'').toLowerCase().trim();if(!b)continue;if(em&&(em===b||(em.indexOf('@')>=0&&em.slice(em.indexOf('@')+1)===b)))return 'E-Mail/Domain steht auf der Opt-out-Liste';if(dom&&dom===b)return 'Domain steht auf der Opt-out-Liste'}return ''}
function akqBlacklistAddEmail(fid,kid){var f=akqFirma(fid),k=akqKontakt(f,kid);var em=String(k&&k.email||'').trim();if(!em){toast('Kein E-Mail-Wert am Kontakt.');return}var a=akqStore();if(a.blacklist.indexOf(em)<0)a.blacklist.push(em);if(k)k.optOut=true;save();render();toast('Auf Opt-out-Liste: '+em)}
function akqBlacklistAdd(){var el=document.getElementById('akq-bl-input');var v=el?String(el.value||'').trim():'';if(!v)return;var a=akqStore();if(a.blacklist.indexOf(v)<0)a.blacklist.push(v);save();render();toast('Opt-out-Eintrag ergänzt: '+v)}
function akqBlacklistDel(i){var a=akqStore();if(a.blacklist[i]!=null){a.blacklist.splice(i,1);save();render()}}
function akqBlacklistPanel(){var a=akqStore();var items=(a.blacklist||[]).map(function(b,i){return '<span class="tag" style="display:inline-block;margin:2px">'+esc(b)+' <button class="btn danger" onclick="akqBlacklistDel('+i+')">×</button></span>'}).join('')||'<span class="muted">Keine Einträge.</span>';return '<div class="panel" style="margin-top:12px"><h3>Opt-out / Blacklist (DSGVO)</h3><p class="muted">E-Mails/Domains, die nicht kontaktiert werden dürfen. Treffer sperren E-Mail-Erzeugung, Mailto und Export.</p><div style="margin:6px 0">'+items+'</div><div style="display:flex;gap:6px"><input id="akq-bl-input" placeholder="E-Mail oder Domain" style="flex:1"><button class="btn" onclick="akqBlacklistAdd()">+ Eintrag</button></div></div>'}

/* Nachfass-Fristen */
function akqSetFollow(fid,kid,v){var k=akqKontakt(akqFirma(fid),kid);if(k){k.nextFollowUp=v;save()}}
function akqFollowPlus(fid,kid,days){var k=akqKontakt(akqFirma(fid),kid);if(!k)return;var d=new Date();d.setDate(d.getDate()+days);k.nextFollowUp=d.toISOString().slice(0,10);save();render()}
function akqFollowClear(fid,kid){var k=akqKontakt(akqFirma(fid),kid);if(k){k.nextFollowUp='';save();render()}}
function akqFollowVal(k){return (k&&k.nextFollowUp)||''}
function akqFollowList(){var a=akqStore(),out=[];a.firmen.forEach(function(f){(f.kontakte||[]).forEach(function(k){if(k.nextFollowUp)out.push({f:f,k:k})})});out.sort(function(x,y){return String(x.k.nextFollowUp).localeCompare(String(y.k.nextFollowUp))});return out}
function akqFollowPanel(){var list=akqFollowList();if(!list.length)return '';var today=akqToday();var rows=list.map(function(o){var due=o.k.nextFollowUp<=today;var col=due?'color:#b00':'';return '<div class="split" style="border-bottom:1px solid var(--line,#ddd);padding:4px 0"><span style="'+col+'">'+(due?'● ':'')+esc(o.k.nextFollowUp)+' — <b>'+esc(o.k.name||o.k.rolle||'Kontakt')+'</b> @ '+esc(o.f.name)+'</span><span><button class="btn" onclick="akqFirmaOpen2(\''+o.f.id+'\')">öffnen</button> <button class="btn" onclick="akqFollowPlus(\''+o.f.id+'\',\''+o.k.id+'\',7)">+7 T</button> <button class="btn danger" onclick="akqFollowClear(\''+o.f.id+'\',\''+o.k.id+'\')">erledigt</button></span></div>'}).join('');return '<div class="panel" style="margin-top:12px"><h3>Anstehende Nachfass-Termine ('+list.length+')</h3>'+rows+'</div>'}

/* Dubletten */
function akqNorm(x){return String(x||'').toLowerCase().replace(/\b(gmbh|ag|kg|ohg|se|mbh|co|kgaa|ug|inc|ltd)\b/g,'').replace(/[^a-z0-9]/g,'').trim()}
function akqDomainOf(f){try{return String(f.website||'').replace(/^https?:\/\//i,'').replace(/\/.*$/,'').toLowerCase()}catch(_){return ''}}
function akqDubletten(){var a=akqStore(),byName={},byDom={},byMail={},hits=[];a.firmen.forEach(function(f){var n=akqNorm(f.name);if(n)(byName[n]=byName[n]||[]).push(f.name);var d=akqDomainOf(f);if(d)(byDom[d]=byDom[d]||[]).push(f.name);(f.kontakte||[]).forEach(function(k){var e=String(k.email||'').toLowerCase().trim();if(e)(byMail[e]=byMail[e]||[]).push(f.name+' / '+(k.name||k.rolle||''))})});Object.keys(byName).forEach(function(n){if(byName[n].length>1)hits.push({typ:'Firmenname',wert:byName[n][0],wo:byName[n].join(', ')})});Object.keys(byDom).forEach(function(d){if(byDom[d].length>1)hits.push({typ:'Domain',wert:d,wo:byDom[d].join(', ')})});Object.keys(byMail).forEach(function(e){if(byMail[e].length>1)hits.push({typ:'E-Mail',wert:e,wo:byMail[e].join(', ')})});return hits}
function akqDublettenPanel(){var hits=akqDubletten();var body=hits.length?hits.map(function(h){return '<div class="split" style="border-bottom:1px solid var(--line,#ddd);padding:4px 0"><span><b>'+esc(h.typ)+':</b> '+esc(h.wert)+'</span><span class="muted">'+esc(h.wo)+'</span></div>'}).join(''):'<p class="muted">Keine Dubletten gefunden.</p>';return '<div class="panel" style="margin-top:12px"><h3>Dubletten-Check ('+hits.length+')</h3>'+body+'</div>'}

/* Erstansprache A/B mit Lernen */
function akqVarAdd(){var a=akqStore();a.firstTouch.variants.push({id:akqId('va'),label:'Variante '+String.fromCharCode(65+(a.firstTouch.variants.length%26)),text:'',sent:0,positive:0});save();render()}
function akqVarSet(id,f,v){var o=akqStore().firstTouch.variants.find(x=>x.id===id);if(o){o[f]=v;save()}}
function akqVarDel(id){if(!akqConfirm('Diese Erstansprache-Variante'))return;var a=akqStore();a.firstTouch.variants=a.firstTouch.variants.filter(x=>x.id!==id);save();render()}
function akqVarRate(v){return (v.sent>0)?(Math.round(100*(v.positive||0)/v.sent)+'%'):'—'}
function akqBestVariant(){var vs=(akqStore().firstTouch.variants||[]).filter(v=>v.sent>=3);vs.sort(function(x,y){return (y.positive/y.sent)-(x.positive/x.sent)});return vs[0]||null}
function akqBestVariantBlock(){var v=akqBestVariant();if(!v||!v.text)return '';return '\n\nBest-performende Erstansprache bisher (als Stilvorlage nutzen, nicht wörtlich kopieren):\n'+String(v.text).slice(0,600)}
function akqVarUse(fid,kid,vid){var k=akqKontakt(akqFirma(fid),kid),v=akqStore().firstTouch.variants.find(x=>x.id===vid);if(!k||!v)return;k.mail=k.mail||{};k.mail.phase=akqStore().phasen[0];k.mail.text=akqAppendSig(v.text||'');k.mail.variant=vid;k.mail.variantSent=false;k.mail._credited=false;save();render()}
function akqVarMarkSent(fid,kid){var k=akqKontakt(akqFirma(fid),kid);if(!k||!k.mail||!k.mail.variant){toast('Keine Variante zugeordnet.');return}if(k.mail.variantSent){toast('Bereits als gesendet gezählt.');return}var v=akqStore().firstTouch.variants.find(x=>x.id===k.mail.variant);if(v){v.sent=(v.sent||0)+1;k.mail.variantSent=true;save();render();toast('Als gesendet gezählt (A/B-Lernen).')}}
function akqVarMaybeCredit(k){var kat=(k&&k.mail&&k.mail.kategorie)||'';if((kat==='Interesse'||kat==='Termin')&&k.mail.variant&&!k.mail._credited){var v=akqStore().firstTouch.variants.find(x=>x.id===k.mail.variant);if(v){v.positive=(v.positive||0)+1;k.mail._credited=true}}}
async function akqVarGen(){var a=akqStore(),r=akqAzureReady();if(!r.ok){toast('KI nicht verfügbar: '+r.reason);return}toast('A/B-Erstansprachen werden erzeugt …');try{var sys='Du bist B2B-Vertriebstexter. Erzeuge ZWEI deutlich unterschiedliche, kurze Erstansprache-Varianten (max. je ca. 110 Wörter) auf Deutsch für das Produkt. Ton: '+(a.absender.ton||'professionell, prägnant')+'. Gib AUSSCHLIESSLICH JSON zurück: [{"label":"A","text":""},{"label":"B","text":""}].';var usr='Produkt/Angebot:\n'+(a.produkt||'')+'\nAbsender: '+(a.absender.name||'')+(a.absender.firma?(', '+a.absender.firma):'');var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:900,temperature:0.6});var arr=akqParseJson(out);if(!Array.isArray(arr))arr=[];var n=0;arr.slice(0,2).forEach(function(o){if(!o||!o.text)return;a.firstTouch.variants.push({id:akqId('va'),label:String(o.label||('Variante '+(a.firstTouch.variants.length+1))).slice(0,20),text:String(o.text).slice(0,1200),sent:0,positive:0});n++});toast(n?('KI hat '+n+' Varianten erzeugt.'):'Keine Varianten erhalten.')}catch(e){toast('KI-Fehler: '+(e&&e.message||e))}save();render()}
function akqVariantsPanel(){var a=akqStore(),vs=a.firstTouch.variants||[],best=akqBestVariant();var rows=vs.map(function(v){var isBest=best&&best.id===v.id;return '<div class="panel" style="margin:6px 0;padding:8px'+(isBest?';border:2px solid #0a0':'')+'"><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><input value="'+esc(v.label)+'" style="width:120px;font-weight:600" oninput="akqVarSet(\''+v.id+'\',\'label\',this.value)"><span class="muted">gesendet '+(v.sent||0)+' · positiv '+(v.positive||0)+' · Quote '+akqVarRate(v)+(isBest?' · ★ beste':'')+'</span><button class="btn danger" style="margin-left:auto" onclick="akqVarDel(\''+v.id+'\')">Löschen</button></div><textarea rows="3" style="width:100%;box-sizing:border-box;margin-top:4px" oninput="akqVarSet(\''+v.id+'\',\'text\',this.value)">'+esc(v.text||'')+'</textarea></div>'}).join('')||'<p class="muted">Noch keine Varianten.</p>';return '<div class="panel" style="margin-top:12px"><h3>Erstansprache: A/B-Varianten mit Lernen</h3><p class="muted">„als gesendet" zählen; wird die Antwort als Interesse/Termin ausgewertet, zählt die Variante positiv. Beste Variante (ab 3 Versänden) fließt in die KI-Erstansprache ein.</p>'+rows+'<div style="margin-top:6px"><button class="btn" onclick="akqVarAdd()">+ Variante</button> <button class="btn" onclick="akqVarGen()">KI: A/B-Varianten</button></div></div>'}

/* Globale E-Mail-Lernschleife */
function akqEmailLearnBlock(){var st=akqStore().emailLearn||[];if(!st.length)return '';return '\n\nGelernte Vertriebsmuster (global, beachten):\n'+st.slice(0,20).map(function(e){return '- Bei „'+e.einwand+'": '+e.strategie}).join('\n')}
function akqPromote(fid,kid){var k=akqKontakt(akqFirma(fid),kid);if(!k||!k.mail||!k.mail.auswertung)return;var a=akqStore();var einwand=String(k.mail.kategorie||'Einwand').slice(0,60),strat=String(k.mail.strategie||k.mail.auswertung).slice(0,240);if(a.emailLearn.some(e=>e.einwand===einwand&&e.strategie===strat)){toast('Muster bereits global gelernt.');return}a.emailLearn.push({einwand:einwand,strategie:strat,at:new Date().toISOString()});save();render();toast('Muster global übernommen – wirkt bei allen (auch neuen) Anbietern.')}
function akqLearnDel(i){var a=akqStore();if(a.emailLearn[i]&&akqConfirm('Dieses gelernte Muster')){a.emailLearn.splice(i,1);save();render()}}
function akqEmailLearnHtml(){var st=akqStore().emailLearn||[];var body=st.length?st.map(function(e,i){return '<div class="split" style="border-bottom:1px solid var(--line,#ddd);padding:4px 0"><span><b>'+esc(e.einwand)+'</b>: '+esc(e.strategie)+'</span><button class="btn danger" onclick="akqLearnDel('+i+')">×</button></div>'}).join(''):'<p class="muted">Noch keine global gelernten Vertriebsmuster.</p>';return '<div class="panel" style="margin-top:12px"><h3>Gelernte Vertriebsmuster (global)</h3>'+body+'</div>'}

/* KI: E-Mail je Phase */
async function akqEmailGen(fid,kid){var f=akqFirma(fid),k=akqKontakt(f,kid);if(!k)return;var _b=akqBlocked(f,k);if(_b){toast('Keine E-Mail: '+_b);return}var r=akqAzureReady();if(!r.ok){toast('KI nicht verfügbar: '+r.reason);return}var a=akqStore(),phase=(k.mail&&k.mail.phase)||a.phasen[0];toast('E-Mail wird erzeugt …');try{var sys='Du bist erfahrener B2B-Vertriebler und schreibst eine Akquise-E-Mail auf Deutsch. Ton: '+(a.absender.ton||'professionell, prägnant')+'. Kurz (max. ca. 130 Wörter), konkreter Nutzen statt Floskeln, eine klare Handlungsaufforderung passend zur Phase. Gib AUSSCHLIESSLICH JSON zurück: {"betreff":"","text":""}.'+akqEmailLearnBlock()+((phase===a.phasen[0])?akqBestVariantBlock():'');var usr='Produkt/Angebot:\n'+(a.produkt||'')+'\n\nPhase: '+phase+'\nZielunternehmen: '+(f.name||'')+'\nBranche: '+akqBrancheName(f.branchenId)+'\nWarum passt die Branche: '+akqBranchePasst(f.branchenId)+'\nAnsprechpartner: '+(k.name||'(unbekannt)')+' — Rolle: '+(k.rolle||'')+'\nAbsender: '+(a.absender.name||'')+(a.absender.firma?(', '+a.absender.firma):'');var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:900,temperature:0.4});var o=akqParseJson(out)||{};k.mail=k.mail||{};k.mail.phase=phase;k.mail.betreff=String(o.betreff||'').slice(0,200)||(k.mail.betreff||'');k.mail.text=akqAppendSig(String(o.text||out||'').slice(0,4000));toast('E-Mail erzeugt.')}catch(e){toast('KI-Fehler: '+(e&&e.message||e))}save();render()}
async function akqEmailEval(fid,kid){var f=akqFirma(fid),k=akqKontakt(f,kid);if(!k)return;var r=akqAzureReady();if(!r.ok){toast('KI nicht verfügbar: '+r.reason);return}var antwort=String((k.mail&&k.mail.antwort)||'').trim();if(!antwort){toast('Bitte zuerst die Antwort des Kunden einfügen.');return}var a=akqStore();toast('Antwort wird ausgewertet …');try{var sys='Du bist B2B-Vertriebscoach. Werte die Kundenantwort aus und formuliere die passende Folge-E-Mail auf Deutsch. Ton: '+(a.absender.ton||'professionell, prägnant')+'. Gib AUSSCHLIESSLICH JSON zurück: {"kategorie":"Interesse|Rückfrage|Einwand|Absage|Termin","auswertung":"1-2 Sätze","strategie":"empfohlene Vorgehensweise in einem Satz","betreff":"","text":""}. Bei klarer Absage höflich und kurz, Tür offen lassen.'+akqEmailLearnBlock();var usr='Produkt/Angebot:\n'+(a.produkt||'')+'\n\nUnternehmen: '+(f.name||'')+' ('+akqBrancheName(f.branchenId)+')\nBisherige Phase: '+((k.mail&&k.mail.phase)||'')+'\nUnsere letzte Mail (Betreff): '+((k.mail&&k.mail.betreff)||'')+'\n\nAntwort des Kunden:\n'+antwort;var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:1100,temperature:0.3});var o=akqParseJson(out)||{};k.mail=k.mail||{};k.mail.kategorie=String(o.kategorie||'').slice(0,40);akqVarMaybeCredit(k);k.mail.auswertung=String(o.auswertung||'').slice(0,400);k.mail.strategie=String(o.strategie||'').slice(0,240);if(o.betreff)k.mail.betreff=String(o.betreff).slice(0,200);if(o.text)k.mail.text=akqAppendSig(String(o.text).slice(0,4000));toast('Antwort ausgewertet'+(k.mail.kategorie?(' ('+k.mail.kategorie+')'):'')+' – Folge-Mail erzeugt.')}catch(e){toast('KI-Fehler: '+(e&&e.message||e))}save();render()}
function akqMailto(fid,kid){var f=akqFirma(fid),k=akqKontakt(f,kid);if(!k||!k.mail)return;var _b=akqBlocked(f,k);if(_b){toast('Gesperrt: '+_b);return}window.location.href='mailto:'+encodeURIComponent(k.email||'')+'?subject='+encodeURIComponent(k.mail.betreff||'')+'&body='+encodeURIComponent(k.mail.text||'')}

/* KI: Marktanbieter & Rollen vorschlagen */
async function akqSuggestAnbieter(){var a=akqStore(),u=akqUi(),bid=u.branche;if(!bid){toast('Bitte zuerst eine Branche wählen.');return}var r=akqAzureReady();if(!r.ok){toast('KI nicht verfügbar: '+r.reason);return}var b=a.branchen.find(x=>x.id===bid);toast('Marktanbieter werden vorgeschlagen …');try{var sys='Du bist Vertriebsrechercheur im DACH-Raum. Nenne reale, bekannte Marktanbieter der genannten Branche, die als Vertriebsziel für das beschriebene Produkt passen. Gib AUSSCHLIESSLICH ein JSON-Array zurück: [{"name":"","website":"","ort":"","begruendung":""}]. Keine erfundenen Firmen.';var usr='Produkt:\n'+(a.produkt||'')+'\n\nBranche: '+(b?b.name:'')+'\nPasst, weil: '+(b?b.passt:'')+'\n\nNenne bis zu 12 passende Marktanbieter.';var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:1400,temperature:0.2});var arr=akqParseJson(out);if(!Array.isArray(arr))arr=[];var added=0;arr.slice(0,12).forEach(function(o){if(!o||!o.name)return;var nm=String(o.name).trim();if(a.firmen.some(f=>f.branchenId===bid&&f.name.toLowerCase()===nm.toLowerCase()))return;a.firmen.push({id:akqId('fi'),branchenId:bid,name:nm,website:String(o.website||'').slice(0,200),ort:String(o.ort||'').slice(0,80),prio:'C',flags:[],notiz:String(o.begruendung||'').slice(0,300),quelle:'KI-Vorschlag (zu prüfen)',kontakte:[],createdAt:new Date().toISOString()});added++});toast(added?('KI hat '+added+' Marktanbieter vorgeschlagen.'):'Keine neuen Vorschläge.')}catch(e){toast('KI-Fehler: '+(e&&e.message||e))}save();render()}
async function akqEnrichKontakte(fid){var f=akqFirma(fid);if(!f)return;var r=akqAzureReady();if(!r.ok){toast('KI nicht verfügbar: '+r.reason);return}toast('Rollen werden vorgeschlagen …');try{var sys='Du bist B2B-Vertriebsrechercheur. Schlage typische FUNKTIONEN/ROLLEN im leitenden Vertrieb vor. Nenne KEINE erfundenen Personennamen. Gib ein JSON-Array zurück: [{"rolle":"","hinweis":""}].';var usr='Unternehmen: '+(f.name||'')+'\nBranche: '+akqBrancheName(f.branchenId)+'\nWebsite: '+(f.website||'');var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:800,temperature:0.2});var arr=akqParseJson(out);if(!Array.isArray(arr))arr=[];f.kontakte=f.kontakte||[];var n=0;arr.slice(0,6).forEach(function(o){if(!o||!o.rolle)return;f.kontakte.push({id:akqId('ko'),name:'',rolle:String(o.rolle).slice(0,80),email:'',tel:'',linkedin:'',quelle:'KI-Rollenvorschlag',notiz:String(o.hinweis||'').slice(0,200),prio:false});n++});toast(n?('KI hat '+n+' Rollen vorgeschlagen.'):'Keine Rollen-Vorschläge.')}catch(e){toast('KI-Fehler: '+(e&&e.message||e))}save();render()}

/* Outlook-Export */
function akqCsvCell(v){v=String(v==null?'':v);return '"'+v.replace(/"/g,'""')+'"'}
function akqOutlookCsv(){var a=akqStore();var head=['First Name','Last Name','Company','Job Title','E-mail Address','Business Phone','Web Page','Notes','Categories'];var rows=[head.map(akqCsvCell).join(',')];var n=0;a.firmen.forEach(function(f){(f.kontakte||[]).forEach(function(k){if(akqBlocked(f,k))return;var nm=String(k.name||'').trim();var parts=nm.split(/\s+/);var last=parts.length>1?parts.pop():'';var first=parts.join(' ');var notes=[k.notiz,k.quelle?('Quelle: '+k.quelle):'','Branche: '+akqBrancheName(f.branchenId),k.linkedin?('LinkedIn: '+k.linkedin):''].filter(Boolean).join(' | ');var cat=['Prio '+(f.prio||'')].concat(f.flags||[]).concat(k.prio?['Schlüsselkontakt']:[]).join(';');rows.push([first,last,f.name,k.rolle,k.email,k.tel,(f.website||k.linkedin||''),notes,cat].map(akqCsvCell).join(','));n++})});return n?('﻿'+rows.join('\r\n')+'\r\n'):''}
function akqExportOutlook(){var csv=akqOutlookCsv();if(!csv){toast('Keine Kontakte zum Exportieren.');return}exportFile('akquise-kontakte-outlook.csv',csv,'text/csv');toast('Kontakte als Outlook-CSV exportiert.')}

/* Implisense v2 */
function implCfg(){return akqStore().implisense}
function implSet(f,v){implCfg()[f]=v;save();if(f==='enabled')render()}
function implPathFill(tpl,map){return String(tpl||'').replace(/\{(\w+)\}/g,function(_,k){return encodeURIComponent(map[k]!=null?map[k]:'')})}
function implJsonFill(tpl,map){return String(tpl).replace(/\{(\w+)\}/g,function(_,k){var v=map[k]!=null?String(map[k]):'';return v.replace(/\\/g,'\\\\').replace(/"/g,'\\"')})}
function implGet(o,keys){for(var i=0;i<keys.length;i++){var k=keys[i];if(o&&o[k]!=null&&o[k]!=='')return o[k]}return ''}
function implList(data){if(Array.isArray(data))return data;if(!data||typeof data!=='object')return [];return data.results||data.companies||data.items||data.hits||data.data||[]}
function implMapCompany(o){o=(o&&(o.company||o.result||o))||{};return {name:implGet(o,['name','companyName','firmenname','legalName']),website:implGet(o,['website','url','homepage','web','domain']),ort:implGet(o,['city','ort','location','town']),employees:implGet(o,['employees','employeeCount','mitarbeiter','numberOfEmployees']),revenue:implGet(o,['revenue','umsatz','turnover','sales']),industry:implGet(o,['industry','branche','sector','nace','naceText']),id:String(implGet(o,['id','companyId','crefoId','implId'])||'')}}
function implMapEvents(data){var arr=Array.isArray(data)?data:((data&&(data.changes||data.events||data.items||data.results||data.data))||[]);if(!Array.isArray(arr))return [];return arr.slice(0,20).map(function(e){return {type:String(implGet(e,['type','eventType','kategorie','category'])||'').slice(0,60),date:String(implGet(e,['date','datum','publishedAt','eventDate','timestamp'])||'').slice(0,10),title:String(implGet(e,['title','titel','headline','text','description','summary'])||'').slice(0,240),url:String(implGet(e,['url','link','source','quelle'])||'').slice(0,240)}}).filter(function(x){return x.title||x.type})}
async function implFetch(path,opts){opts=opts||{};var c=implCfg();var base=String(c.baseUrl||'').replace(/\/+$/,'');if(!base)throw new Error('Keine Basis-URL');var url=base+path;var proxy=((state.settings&&state.settings.corsProxy)||'').trim();var target=proxy?proxy+encodeURIComponent(url):url;var headers={'Accept':'application/json'};if(c.apiKey)headers[c.authHeader||'Authorization']=(c.authPrefix||'')+c.apiKey;var init={method:(opts.method||'GET'),headers:headers};if(opts.body!=null){headers['Content-Type']='application/json';init.body=opts.body}try{var res=await fetch(target,init);var txt=await res.text();var data=null;try{data=JSON.parse(txt)}catch(_){}try{log('INFO','implisense',{url:url.replace(/([?&](key|token|apikey)=)[^&]*/gi,'$1***'),status:res.status})}catch(_){}if(!res.ok)throw new Error('HTTP '+res.status+(txt?(': '+String(txt).slice(0,160)):''));return data!=null?data:txt}catch(e){try{log('ERROR','implisense',{url:url,error:String(e&&e.message||e)})}catch(_){}throw e}}
async function implSearch(q){var c=implCfg();var m=String(c.searchMethod||'GET').toUpperCase();if(m==='POST'){var body=implJsonFill(c.searchBody||'{"query":"{q}"}',{q:q});return implFetch(c.searchPath||'/search',{method:'POST',body:body})}return implFetch(implPathFill(c.searchPath||'/search?q={q}',{q:q}))}
async function implTest(){var c=implCfg();if(!c.baseUrl){toast('Keine Implisense-Basis-URL.');return}toast('Implisense-Verbindung wird getestet …');try{var d=await implSearch('test');c.status='ok';toast('Implisense erreichbar ('+implList(d).length+' Treffer für „test").')}catch(e){c.status='Fehler: '+(e&&e.message||e);toast('Implisense-Fehler: '+(e&&e.message||e))}save();render()}
async function implSearchImport(){var c=implCfg();var el=document.getElementById('akq-impl-q');var q=el?String(el.value||'').trim():'';if(!q){toast('Bitte Suchbegriff eingeben.');return}var a=akqStore(),bid=akqUi().branche||((a.branchen.find(function(b){return b.aktiv})||{}).id)||'';toast('Implisense-Suche …');try{var d=await implSearch(q);var list=implList(d).slice(0,15);var added=0;list.forEach(function(o){var m=implMapCompany(o);if(!m.name)return;if(a.firmen.some(function(f){return f.branchenId===bid&&String(f.name).toLowerCase()===String(m.name).toLowerCase()}))return;a.firmen.push({id:akqId('fi'),branchenId:bid,name:String(m.name),website:String(m.website||''),ort:String(m.ort||''),prio:'C',flags:[],notiz:'',quelle:'Implisense',implId:m.id,firmographics:{employees:m.employees,revenue:m.revenue,industry:m.industry},kontakte:[],createdAt:new Date().toISOString()});added++});toast(added?('Implisense: '+added+' Firmen importiert.'):'Keine neuen Treffer.')}catch(e){toast('Implisense-Fehler: '+(e&&e.message||e))}save();render()}
async function implEnrich(fid){var f=akqFirma(fid);if(!f)return;var c=implCfg();toast('Implisense-Anreicherung …');try{var id=f.implId||'';if(!id){var ds=await implSearch(f.name);var first=implList(ds)[0];id=first?implMapCompany(first).id:'';if(id)f.implId=id}if(id&&c.companyPath){var company=await implFetch(implPathFill(c.companyPath,{id:id}));var m=implMapCompany(company);f.firmographics=Object.assign(f.firmographics||{},{employees:m.employees||(f.firmographics||{}).employees,revenue:m.revenue||(f.firmographics||{}).revenue,industry:m.industry||(f.firmographics||{}).industry});if(!f.website&&m.website)f.website=m.website;if(!f.ort&&m.ort)f.ort=m.ort}if(id&&c.eventsPath){try{var ev=await implFetch(implPathFill(c.eventsPath,{id:id}));f.events=implMapEvents(ev)}catch(_){}}f.enrichedAt=new Date().toISOString();toast('Implisense: Firmendaten'+((f.events&&f.events.length)?(' + '+f.events.length+' Ereignisse'):'')+' übernommen'+(id?'':' (keine ID gefunden)')+'.')}catch(e){toast('Implisense-Fehler: '+(e&&e.message||e))}save();render()}
function akqImplFirmaHtml(f){var c=implCfg();if(!c.enabled)return '';var fg=f.firmographics||{};var info=(fg.employees||fg.revenue||fg.industry)?('<div class="muted" style="margin-top:4px">Mitarbeiter: '+esc(String(fg.employees||'–'))+' · Umsatz: '+esc(String(fg.revenue||'–'))+' · Branche: '+esc(String(fg.industry||'–'))+'</div>'):'';var ev=(f.events&&f.events.length)?('<div style="margin-top:4px"><small class="muted">Implisense-Ereignisse:</small>'+f.events.slice(0,8).map(function(e){return '<div class="split" style="border-bottom:1px solid var(--line,#ddd);padding:3px 0"><span>'+(e.date?('<span class="muted">'+esc(e.date)+'</span> '):'')+esc(e.type||'')+(e.title?(' — '+esc(e.title)):'')+'</span>'+(e.url?('<a href="'+esc(e.url)+'" target="_blank" rel="noopener">Quelle</a>'):'')+'</div>'}).join('')+'</div>'):'';return '<div style="margin-top:8px"><button class="btn" onclick="implEnrich(\''+f.id+'\')">Implisense: anreichern</button>'+info+ev+'</div>'}
function akqImplisensePanel(){var c=implCfg();var brOpts=akqStore().branchen.filter(function(b){return b.aktiv}).map(function(b){return '<option value="'+esc(b.id)+'">'+esc(b.name)+'</option>'}).join('');return '<div class="panel" style="margin-top:12px"><h3>Implisense-Anbindung (Firmendaten &amp; Signale)</h3><p class="muted">REST-API v2 für Firmenstammdaten und Veränderungs-Ereignisse. Schlüssel bleibt lokal. Basis-URL, Pfade und Auth müssen zum gebuchten Zugang passen (docs.implisense.com/v2/docs). Bei „Failed to fetch" blockt CORS den Direktaufruf — oben unter „Quellen & Crawling" ein CORS-Proxy-Präfix setzen (oder lokalen Proxy) und die App mit --disable-web-security starten.</p><label class="muted" style="display:flex;gap:4px;align-items:center;margin:4px 0"><input type="checkbox" '+(c.enabled?'checked':'')+' onchange="implSet(\'enabled\',this.checked)">aktiv</label><div style="display:flex;gap:6px;flex-wrap:wrap"><input value="'+esc(c.baseUrl||'')+'" placeholder="Basis-URL" style="flex:1;min-width:220px" oninput="implSet(\'baseUrl\',this.value)"><input value="'+esc(c.apiKey||'')+'" type="password" placeholder="API-Schlüssel" style="flex:1;min-width:180px" oninput="implSet(\'apiKey\',this.value)"></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(c.searchMethod||'')+'" placeholder="Such-Methode (GET/POST)" style="width:150px" oninput="implSet(\'searchMethod\',this.value)"><input value="'+esc(c.searchBody||'')+'" placeholder="Firmen-Such-Body JSON mit {q}" style="flex:1;min-width:200px" oninput="implSet(\'searchBody\',this.value)"></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(c.searchBranchBody||'')+'" placeholder="Branchen-Such-Body JSON mit {q}" style="flex:1;min-width:220px" oninput="implSet(\'searchBranchBody\',this.value)"></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(c.searchPath||'')+'" placeholder="Suchpfad" style="flex:1;min-width:150px" oninput="implSet(\'searchPath\',this.value)"><input value="'+esc(c.companyPath||'')+'" placeholder="Firmenpfad ({id})" style="flex:1;min-width:180px" oninput="implSet(\'companyPath\',this.value)"><input value="'+esc(c.eventsPath||'')+'" placeholder="Ereignispfad ({id})" style="flex:1;min-width:180px" oninput="implSet(\'eventsPath\',this.value)"></div><div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:6px"><button class="btn" onclick="implTest()">Verbindung testen</button>'+(c.status?('<span class="muted">Status: '+esc(c.status)+'</span>'):'')+'</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><input id="akq-impl-q" placeholder="Firmensuche (Name/Stichwort) → Import in gewählte Branche" style="flex:1;min-width:220px"><button class="btn" onclick="implSearchImport()">Suchen &amp; importieren</button></div><div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:8px"><span class="muted">Alle Firmen einer Branche:</span><select id="akq-impl-branch">'+brOpts+'</select><button class="btn primary" onclick="akqImplBranchImport()">Branche importieren</button></div></div>'}

/* E-Mail-Block + Kontakt-/Firmen-/Branchen-Rendering */
function akqMailBlock(f,k){var a=akqStore();var m=k.mail||{};var opt=a.phasen.map(function(p){return '<option '+(((m.phase||a.phasen[0])===p)?'selected':'')+'>'+esc(p)+'</option>'}).join('');var learnBtn=m.auswertung?(' <button class="btn" onclick="akqPromote(\''+f.id+'\',\''+k.id+'\')" title="Als globales Muster übernehmen">↑ Muster global lernen</button>'):'';var block=akqBlocked(f,k);var warn=block?('<div class="panel" style="margin-top:6px;padding:6px;border:1px solid #b00;color:#b00">Opt-out aktiv: '+esc(block)+'. Versand gesperrt.</div>'):'';var isFirst=((m.phase||a.phasen[0])===a.phasen[0]);var vopts=(a.firstTouch.variants||[]).map(function(v){return '<option value="'+v.id+'">'+esc(v.label)+' ('+akqVarRate(v)+')</option>'}).join('');var vsel=(isFirst&&vopts)?('<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:6px"><span class="muted">A/B:</span><select id="akq-var-'+k.id+'">'+vopts+'</select><button class="btn" onclick="akqVarUse(\''+f.id+'\',\''+k.id+'\',document.getElementById(\'akq-var-'+k.id+'\').value)">Variante übernehmen</button><button class="btn" onclick="akqVarMarkSent(\''+f.id+'\',\''+k.id+'\')">als gesendet</button></div>'):'';var follow='<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:6px"><span class="muted">Nachfassen am</span><input type="date" value="'+esc(akqFollowVal(k))+'" onchange="akqSetFollow(\''+f.id+'\',\''+k.id+'\',this.value)"><button class="btn" onclick="akqFollowPlus(\''+f.id+'\',\''+k.id+'\',7)">+7 T</button><button class="btn" onclick="akqFollowPlus(\''+f.id+'\',\''+k.id+'\',14)">+14 T</button></div>';var opt2='<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:6px"><label class="muted" style="display:flex;gap:4px;align-items:center"><input type="checkbox" '+(k.optOut?'checked':'')+' onchange="akqKontaktToggleOpt(\''+f.id+'\',\''+k.id+'\')">Opt-out</label><button class="btn" onclick="akqBlacklistAddEmail(\''+f.id+'\',\''+k.id+'\')">E-Mail auf Opt-out-Liste</button></div>';
 return '<details style="margin-top:8px"><summary class="muted">E-Mail / Akquise-Phase</summary><div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap;align-items:center"><select onchange="akqSetPhase(\''+f.id+'\',\''+k.id+'\',this.value)">'+opt+'</select><button class="btn primary" onclick="akqEmailGen(\''+f.id+'\',\''+k.id+'\')">KI: E-Mail erzeugen</button><button class="btn" onclick="akqMailto(\''+f.id+'\',\''+k.id+'\')">In Outlook öffnen</button></div>'+warn+vsel+follow+opt2+'<input value="'+esc(m.betreff||'')+'" placeholder="Betreff" style="width:100%;box-sizing:border-box;margin-top:6px" oninput="akqMailSet(\''+f.id+'\',\''+k.id+'\',\'betreff\',this.value)"><textarea rows="7" style="width:100%;box-sizing:border-box;margin-top:4px" placeholder="E-Mail-Text" oninput="akqMailSet(\''+f.id+'\',\''+k.id+'\',\'text\',this.value)">'+esc(m.text||'')+'</textarea><div class="muted" style="margin-top:8px">Antwort des Kunden (für Auswertung &amp; Folge-Mail):</div><textarea rows="4" style="width:100%;box-sizing:border-box;margin-top:2px" placeholder="Antwort hier einfügen …" oninput="akqMailSet(\''+f.id+'\',\''+k.id+'\',\'antwort\',this.value)">'+esc(m.antwort||'')+'</textarea><div style="margin-top:6px"><button class="btn primary" onclick="akqEmailEval(\''+f.id+'\',\''+k.id+'\')">KI: Antwort auswerten &amp; Folge-Mail</button>'+learnBtn+'</div>'+(m.auswertung?('<div class="panel" style="margin-top:6px;padding:8px"><b>Auswertung'+(m.kategorie?(' – '+esc(m.kategorie)):'')+':</b> '+esc(m.auswertung)+(m.strategie?('<br><span class="muted">Empfehlung: '+esc(m.strategie)+'</span>'):'')+'</div>'):'')+'</details>'}
function akqKontakteHtml(f){var ko=f.kontakte||[];var rows=ko.map(function(k){return '<div class="panel" style="margin:6px 0;padding:8px"><div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center"><input value="'+esc(k.name)+'" placeholder="Name" style="flex:1;min-width:140px" oninput="akqKontaktSet(\''+f.id+'\',\''+k.id+'\',\'name\',this.value)"><input value="'+esc(k.rolle)+'" placeholder="Rolle (z. B. Vertriebsleitung)" style="flex:1;min-width:160px" oninput="akqKontaktSet(\''+f.id+'\',\''+k.id+'\',\'rolle\',this.value)"><button class="btn '+(k.prio?'primary':'')+'" onclick="akqKontaktPrio(\''+f.id+'\',\''+k.id+'\')" title="Schlüsselkontakt">★</button><button class="btn danger" onclick="akqKontaktDel(\''+f.id+'\',\''+k.id+'\')">Löschen</button></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(k.email)+'" placeholder="E-Mail" style="flex:1;min-width:160px" oninput="akqKontaktSet(\''+f.id+'\',\''+k.id+'\',\'email\',this.value)"><input value="'+esc(k.tel)+'" placeholder="Telefon" style="flex:1;min-width:120px" oninput="akqKontaktSet(\''+f.id+'\',\''+k.id+'\',\'tel\',this.value)"><input value="'+esc(k.linkedin)+'" placeholder="LinkedIn/Quelle-URL" style="flex:1;min-width:160px" oninput="akqKontaktSet(\''+f.id+'\',\''+k.id+'\',\'linkedin\',this.value)"></div>'+akqMailBlock(f,k)+'</div>'}).join('');return rows+'<div style="margin-top:6px"><button class="btn" onclick="akqKontaktAdd(\''+f.id+'\')">+ Kontakt</button> <button class="btn" onclick="akqEnrichKontakte(\''+f.id+'\')">KI: Rollen vorschlagen</button> <span class="muted">Suchlinks: '+akqSearchLinks(f)+'</span></div>'}
function akqBranchenHtml(){var a=akqStore();return a.branchen.map(function(b){return '<div class="panel" style="margin:6px 0;padding:8px"><div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center"><input value="'+esc(b.name)+'" style="flex:1;min-width:200px;font-weight:600" oninput="akqBrancheSet(\''+b.id+'\',\'name\',this.value)"><button class="btn '+(b.geeignet?'primary':'')+'" onclick="akqBrancheToggle(\''+b.id+'\',\'geeignet\')">'+(b.geeignet?'geeignet':'weniger geeignet')+'</button><label class="muted" style="display:flex;gap:4px;align-items:center"><input type="checkbox" '+(b.aktiv?'checked':'')+' onchange="akqBrancheToggle(\''+b.id+'\',\'aktiv\')">aktiv</label><button class="btn danger" onclick="akqBrancheDel(\''+b.id+'\')">Löschen</button></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(b.passt||'')+'" placeholder="Passt, weil …" style="flex:1;min-width:220px" oninput="akqBrancheSet(\''+b.id+'\',\'passt\',this.value)"><input value="'+esc(b.anpassen||'')+'" placeholder="Anzupassen …" style="flex:1;min-width:220px" oninput="akqBrancheSet(\''+b.id+'\',\'anpassen\',this.value)"></div></div>'}).join('')+'<button class="btn" onclick="akqBrancheAdd()">+ Branche</button>'}
function akqFirmaDetail(f){return '<div style="margin-top:4px"><input value="'+esc(f.name)+'" placeholder="Firmenname" style="width:100%;box-sizing:border-box;font-weight:600" oninput="akqFirmaSet(\''+f.id+'\',\'name\',this.value)"><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(f.website||'')+'" placeholder="Webadresse" style="flex:1;min-width:180px" oninput="akqFirmaSet(\''+f.id+'\',\'website\',this.value)"><input value="'+esc(f.ort||'')+'" placeholder="Ort" style="flex:1;min-width:120px" oninput="akqFirmaSet(\''+f.id+'\',\'ort\',this.value)"><select onchange="akqFirmaSet(\''+f.id+'\',\'prio\',this.value);render()" title="Priorität">'+['A','B','C','D'].map(function(p){return '<option '+((f.prio||'B')===p?'selected':'')+'>'+p+'</option>'}).join('')+'</select><button class="btn '+((f.flags||[]).indexOf('heiß')>=0?'primary':'')+'" onclick="akqFirmaFlag(\''+f.id+'\',\'heiß\')">heiß</button><button class="btn '+((f.flags||[]).indexOf('nachfassen')>=0?'primary':'')+'" onclick="akqFirmaFlag(\''+f.id+'\',\'nachfassen\')">nachfassen</button><button class="btn '+(f.optOut?'danger':'')+'" onclick="akqFirmaToggleOpt(\''+f.id+'\')">'+(f.optOut?'Opt-out':'kontaktierbar')+'</button></div><input value="'+esc(f.notiz||'')+'" placeholder="Firmenbeschreibung / Notiz" style="width:100%;box-sizing:border-box;margin-top:6px" oninput="akqFirmaSet(\''+f.id+'\',\'notiz\',this.value)">'+(f.quelle?('<div class="muted" style="margin-top:4px">Quelle: '+esc(f.quelle)+'</div>'):'')+akqImplFirmaHtml(f)+'<h4 style="margin:10px 0 4px">Ansprechpartner</h4>'+akqKontakteHtml(f)+'</div>'}
function akqFirmenHtml(){var a=akqStore(),u=akqUi();var list=a.firmen.filter(function(f){return !u.branche||f.branchenId===u.branche});list.sort(function(x,y){return akqPrioRank(x.prio)-akqPrioRank(y.prio)||String(x.name).localeCompare(String(y.name))});if(!list.length)return '<p class="muted">Noch keine Firmen in dieser Auswahl. Oben per „Branchensuche" oder „+ Marktanbieter" hinzufügen.</p>';var head='<tr><th>Firmenname</th><th>Ort</th><th>Webadresse</th><th>Firmenbeschreibung</th><th>E-Mail</th><th>Telefon</th><th>Ansprechpartner</th><th></th></tr>';var rows=list.map(function(f){var open=u.firma===f.id;var k=(f.kontakte||[])[0]||{};var ap=(k.name||'')+((k.name&&k.rolle)?' ':'')+(k.rolle?('('+k.rolle+')'):'');var wurl=/^https?:\/\//i.test(f.website||'')?f.website:('https://'+(f.website||''));var web=f.website?('<a href="'+esc(wurl)+'" target="_blank" rel="noopener">'+esc(f.website)+'</a>'):'';var tr='<tr><td><b>'+esc(f.name)+'</b>'+(f.quelle?('<div class="muted" style="font-size:11px">'+esc(f.quelle)+'</div>'):'')+'</td><td>'+esc(f.ort||'')+'</td><td>'+web+'</td><td>'+esc(f.notiz||'')+'</td><td>'+(k.email?('<a href="mailto:'+esc(k.email)+'">'+esc(k.email)+'</a>'):'')+'</td><td>'+esc(k.tel||'')+'</td><td>'+esc(ap)+'</td><td style="white-space:nowrap"><button class="btn" onclick="akqFirmaOpen(\''+f.id+'\')" title="Details / Kontakte bearbeiten">'+(open?'▾':'▸')+'</button> <button class="btn danger" onclick="akqFirmaDel(\''+f.id+'\')" title="Löschen">×</button></td></tr>';if(open)tr+='<tr><td colspan="8">'+akqFirmaDetail(f)+'</td></tr>';return tr}).join('');return '<div class="table-wrap"><table class="table"><thead>'+head+'</thead><tbody>'+rows+'</tbody></table></div>'}

function akquise(){var a=akqStore(),u=akqUi();var brOpts='<option value="">Alle aktiven Branchen</option>'+a.branchen.filter(b=>b.aktiv).map(function(b){return '<option value="'+b.id+'" '+(u.branche===b.id?'selected':'')+'>'+esc(b.name)+'</option>'}).join('');return '<section class="view"><h1>Akquise – Vermarktung von Tender AI</h1><p class="muted">Marktanbieter je Branche sammeln, Ansprechpartner pflegen, priorisieren, für Outlook exportieren und KI-E-Mails je Phase erzeugen. Global gespeichert, bleibt lokal.</p>'+akqBranchenSuchePanel()
 +'<div class="panel"><h3>Produkt-/Absendertext (fließt in die KI-E-Mails)</h3><textarea rows="3" style="width:100%;box-sizing:border-box" oninput="akqProdSet(\'produkt\',this.value)">'+esc(a.produkt||'')+'</textarea><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><input value="'+esc(a.absender.name||'')+'" placeholder="Absender-Name" style="flex:1;min-width:140px" oninput="akqAbsSet(\'name\',this.value)"><input value="'+esc(a.absender.firma||'')+'" placeholder="Absender-Firma" style="flex:1;min-width:140px" oninput="akqAbsSet(\'firma\',this.value)"></div><textarea rows="2" style="width:100%;box-sizing:border-box;margin-top:6px" placeholder="Signatur" oninput="akqAbsSet(\'signatur\',this.value)">'+esc(a.absender.signatur||'')+'</textarea></div>'
 +'<div class="panel" style="margin-top:12px"><h3>Branchen (pflegbare Liste)</h3>'+akqBranchenHtml()+'</div>'
 +'<div class="panel" style="margin-top:12px"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><h3 style="margin:0">Marktanbieter</h3><select onchange="akqUiBranche(this.value)">'+brOpts+'</select><button class="btn" onclick="akqFirmaAdd()">+ Marktanbieter</button><button class="btn" onclick="akqSuggestAnbieter()">KI: Marktanbieter vorschlagen</button><button class="btn" onclick="akqExportOutlook()">Kontakte → Outlook-CSV</button></div><div style="margin-top:8px">'+akqFirmenHtml()+'</div></div>'
 +akqFollowPanel()+akqDublettenPanel()+akqVariantsPanel()+akqEmailLearnHtml()+akqBlacklistPanel()
 +'</section>'}


function akqImportFirma(bid,m){var a=akqStore();var nm=String(m.name||'').trim();if(!nm)return false;if(a.firmen.some(function(f){return f.branchenId===bid&&String(f.name).toLowerCase()===nm.toLowerCase()}))return false;a.firmen.push({id:akqId('fi'),branchenId:bid,name:nm,website:String(m.website||''),ort:String(m.ort||''),prio:'C',flags:[],notiz:String(m.notiz||''),quelle:m.quelle||'',implId:m.implId||'',firmographics:m.firmographics||{},kontakte:[],createdAt:new Date().toISOString()});return true}
async function akqSearchBranche(bid){var a=akqStore();var b=a.branchen.find(function(x){return x.id===bid});if(!b)return 0;var added=0;if(a.implisense&&a.implisense.enabled){try{var d=await implSearchBranch(b.implQuery||b.name);implList(d).slice(0,15).forEach(function(o){var m=implMapCompany(o);if(akqImportFirma(bid,{name:m.name,website:m.website,ort:m.ort,quelle:'Implisense',implId:m.id,firmographics:{employees:m.employees,revenue:m.revenue,industry:m.industry}}))added++});return added}catch(e){}}var r=akqAzureReady();if(r.ok){try{var sys='Du bist Vertriebsrechercheur im DACH-Raum. Nenne reale, bekannte Marktanbieter der Branche, die als Vertriebsziel fuer das Produkt passen. Gib AUSSCHLIESSLICH ein JSON-Array zurueck: [{"name":"","website":"","ort":"","begruendung":""}]. Keine erfundenen Firmen.';var usr='Produkt: '+(a.produkt||'')+' | Branche: '+b.name+' | Passt: '+(b.passt||'')+' | Bis zu 12 passende Marktanbieter.';var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:1400,temperature:0.2});var arr=akqParseJson(out);if(Array.isArray(arr))arr.slice(0,12).forEach(function(o){if(o&&o.name&&akqImportFirma(bid,{name:o.name,website:o.website,ort:o.ort,notiz:o.begruendung,quelle:'KI-Vorschlag (zu pruefen)'}))added++})}catch(e){}}return added}
async function akqProfilSuche(){var p=activeProfile();var bids=(p.branchen||[]);if(!bids.length){toast('Im Profil keine Zielbranchen gewaehlt.');return}toast('Branchensuche laeuft …');var total=0;for(var i=0;i<bids.length;i++){try{total+=await akqSearchBranche(bids[i])}catch(e){}}view='akquise';try{akqUi().branche=bids.length===1?bids[0]:''}catch(e){}save();render();toast('Branchensuche fertig: '+total+' Firmen importiert.')}
async function implSearchBranch(term){var c=implCfg();var tpl=c.searchBranchBody||'{"industry":"{q}"}';var body=implJsonFill(tpl,{q:term});return implFetch(c.searchPath||'/search',{method:'POST',body:body})}
async function akqImplBranchImport(){var el=document.getElementById('akq-impl-branch');var bid=el?el.value:'';var a=akqStore();var b=a.branchen.find(function(x){return x.id===bid});if(!b){toast('Bitte Branche wählen.');return}toast('Implisense-Branchensuche …');var added=0;try{var d=await implSearchBranch(b.implQuery||b.name);implList(d).slice(0,50).forEach(function(o){var m=implMapCompany(o);if(akqImportFirma(bid,{name:m.name,website:m.website,ort:m.ort,quelle:'Implisense',implId:m.id,firmographics:{employees:m.employees,revenue:m.revenue,industry:m.industry}}))added++})}catch(e){toast('Implisense-Fehler: '+(e&&e.message||e));return}view='akquise';try{akqUi().branche=bid}catch(e){}save();render();toast('Branche importiert: '+added+' Firmen.')}
function akqSelectedBsuche(){return [].slice.call(document.querySelectorAll('[data-bsuche]:checked')).map(function(e){return e.getAttribute('data-bsuche')})}
function akqBranchenSuchePanel(){var a=akqStore();var cbs=a.branchen.filter(function(b){return b.aktiv}).map(function(b){return '<label style="display:inline-flex;gap:4px;align-items:center;margin:2px 12px 2px 0"><input type="checkbox" data-bsuche="'+esc(b.id)+'">'+esc(b.name)+'</label>'}).join('')||'<span class="muted">Keine aktiven Branchen – unter „Branchen" aktivieren.</span>';return '<div class="panel"><h3>Branchensuche – Firmen finden (ohne Firmennamen)</h3><p class="muted">Eine oder mehrere Branchen wählen und passende Unternehmen finden lassen – ganz ohne Firmennamen. „Per KI" nutzt die Azure-Anbindung (funktioniert direkt). „Per Implisense" nutzt die hinterlegte API (nur mit Zugang/Proxy). Mehrfach klickbar – findet jeweils weitere, ohne Dubletten.</p><div style="margin:8px 0">'+cbs+'</div><div class="toolbar"><button class="btn primary" onclick="akqKiBranchenSuche()">Firmen per KI finden</button><button class="btn" onclick="akqImplBranchenSuche()">Firmen per Implisense finden</button></div></div>'}
async function akqKiFirmenFinden(bid){var a=akqStore();var b=a.branchen.find(function(x){return x.id===bid});if(!b)return 0;var have=a.firmen.filter(function(f){return f.branchenId===bid}).map(function(f){return f.name}).slice(0,50);var sys='Du bist Vertriebsrechercheur im DACH-Raum. Nenne reale, existierende Unternehmen der genannten Branche als Vertriebsziele fuer das Produkt. Gib AUSSCHLIESSLICH ein JSON-Array zurueck: [{"name":"","website":"","ort":"","begruendung":""}]. Keine erfundenen Firmen und keine Dubletten zu den bereits bekannten.';var usr='Produkt: '+(a.produkt||'')+' | Branche: '+b.name+' | Passt, weil: '+(b.passt||'')+' | Bereits bekannt (NICHT erneut nennen): '+(have.join(', ')||'-')+' | Nenne bis zu 20 weitere passende Unternehmen dieser Branche.';var out=await azureChat([{role:'system',content:sys},{role:'user',content:usr}],{maxTokens:1800,temperature:0.3});var arr=akqParseJson(out);var added=0;if(Array.isArray(arr))arr.slice(0,20).forEach(function(o){if(o&&o.name&&akqImportFirma(bid,{name:o.name,website:o.website,ort:o.ort,notiz:o.begruendung,quelle:'KI-Branchensuche (zu pruefen)'}))added++});return added}
async function akqKiBranchenSuche(){var bids=akqSelectedBsuche();if(!bids.length){toast('Bitte mindestens eine Branche wählen.');return}var r=akqAzureReady();if(!r.ok){toast('KI nicht verfügbar: '+r.reason);return}toast('KI sucht Firmen der gewählten Branche(n) …');var total=0;for(var i=0;i<bids.length;i++){try{total+=await akqKiFirmenFinden(bids[i])}catch(e){}}try{akqUi().branche=bids.length===1?bids[0]:''}catch(e){}save();render();toast('KI-Branchensuche: '+total+' Firmen gefunden.')}
async function akqImplBranchenSuche(){var bids=akqSelectedBsuche();if(!bids.length){toast('Bitte mindestens eine Branche wählen.');return}var a=akqStore();if(!(a.implisense&&a.implisense.enabled)){toast('Implisense ist nicht aktiv – unter „Quellen & Crawling" aktivieren.');return}toast('Implisense-Branchensuche …');var total=0;for(var i=0;i<bids.length;i++){try{total+=await akqSearchBranche(bids[i])}catch(e){}}try{akqUi().branche=bids.length===1?bids[0]:''}catch(e){}save();render();toast('Implisense-Branchensuche: '+total+' Firmen.')}
try{Object.assign(window,{akqFirmaDetail,akqKiBranchenSuche,akqImplBranchenSuche,akqKiFirmenFinden,akqSelectedBsuche,akqBranchenSuchePanel,implSearchBranch,akqImplBranchImport,akqProfilSuche,akqSearchBranche,akqImportFirma,akqOutlookCsv,akqAbsSet,akqAppendSig,akqAzureReady,akqBestVariant,akqBestVariantBlock,akqBlacklistAdd,akqBlacklistAddEmail,akqBlacklistDel,akqBlacklistPanel,akqBlocked,akqBrancheAdd,akqBrancheDel,akqBrancheName,akqBranchePasst,akqBrancheSet,akqBrancheToggle,akqBranchenHtml,akqConfirm,akqCsvCell,akqDefaults,akqDomainOf,akqDubletten,akqDublettenPanel,akqEmailEval,akqEmailGen,akqEmailLearnBlock,akqEmailLearnHtml,akqEnrichKontakte,akqExportOutlook,akqFirma,akqFirmaAdd,akqFirmaDel,akqFirmaFlag,akqFirmaOpen,akqFirmaOpen2,akqFirmaSet,akqFirmaToggleOpt,akqFirmenHtml,akqFollowClear,akqFollowList,akqFollowPanel,akqFollowPlus,akqFollowVal,akqId,akqImplFirmaHtml,akqImplisensePanel,akqKontakt,akqKontaktAdd,akqKontaktDel,akqKontaktPrio,akqKontaktSet,akqKontaktToggleOpt,akqKontakteHtml,akqLearnDel,akqMailBlock,akqMailSet,akqMailto,akqNorm,akqParseJson,akqPrioRank,akqProdSet,akqPromote,akqSearchLinks,akqSetFollow,akqSetPhase,akqStore,akqSuggestAnbieter,akqToday,akqUi,akqUiBranche,akqVarAdd,akqVarDel,akqVarGen,akqVarMarkSent,akqVarMaybeCredit,akqVarRate,akqVarSet,akqVarUse,akqVariantsPanel,akquise,implCfg,implEnrich,implFetch,implGet,implJsonFill,implList,implMapCompany,implMapEvents,implPathFill,implSearch,implSearchImport,implSet,implTest})}catch(_){}
function render(){const main=document.querySelector("#main");main.innerHTML=({dashboard,companies,raw,tags:tagsView,clusters,sales,tender,profile:profileView,sources,azure,diagnostics,akquise}[view]||dashboard)();document.querySelectorAll(".nav").forEach(n=>n.classList.toggle("active",n.dataset.view===view));bind()}
function bind(){document.querySelectorAll("[data-view]").forEach(n=>n.onclick=()=>{view=n.dataset.view;render()});document.querySelectorAll('[data-action="add"]').forEach(n=>n.onclick=()=>openCompany());document.querySelectorAll('[data-action="crawlAll"]').forEach(n=>n.onclick=()=>{state.companies.forEach(c=>crawlCompany(c));render();toast("Alle Unternehmen gecrawlt")});document.querySelectorAll("[data-crawl]").forEach(n=>n.onclick=()=>{const c=state.companies.find(x=>x.company_id===n.dataset.crawl);if(c){crawlCompany(c);render();toast("Crawling abgeschlossen")}});document.querySelectorAll("[data-edit]").forEach(n=>n.onclick=()=>openCompany(n.dataset.edit));document.querySelectorAll("[data-delete]").forEach(n=>n.onclick=()=>{state.companies=state.companies.filter(c=>c.company_id!==n.dataset.delete);save();render();toast("Unternehmen gelöscht")});document.querySelectorAll('[data-action="backup"]').forEach(n=>n.onclick=backup);document.querySelectorAll('[data-action="import"]').forEach(n=>n.onclick=()=>document.querySelector("#fileImport").click());document.querySelector("#fileImport").onchange=e=>importData(e.target.files[0]);document.querySelectorAll('[data-action="exportClusters"]').forEach(n=>n.onclick=exportClusters);document.querySelectorAll('[data-action="exportTender"]').forEach(n=>n.onclick=exportTender);document.querySelectorAll('[data-action="exportCsv"]').forEach(n=>n.onclick=()=>{exportAnalysisCSV();toast("CSV exportiert")});document.querySelectorAll('[data-action="exportJsonl"]').forEach(n=>n.onclick=()=>{exportAnalysisJSONL();toast("JSONL exportiert")});document.querySelectorAll('[data-action="saveAzure"]').forEach(n=>n.onclick=()=>{state.azure.endpoint=document.querySelector("#azEndpoint").value.trim();state.azure.deployment=document.querySelector("#azDeployment").value.trim();state.azure.apiVersion=document.querySelector("#azVersion").value;state.azure.apiKey=document.querySelector("#azKey").value.trim();save();render();toast("Azure-Konfiguration gespeichert")});document.querySelectorAll('[data-action="testAzure"]').forEach(n=>n.onclick=()=>{state.azure.endpoint=document.querySelector("#azEndpoint").value.trim();state.azure.deployment=document.querySelector("#azDeployment").value.trim();state.azure.apiVersion=document.querySelector("#azVersion").value;state.azure.apiKey=document.querySelector("#azKey").value.trim();save();testAzure()});document.querySelectorAll('[data-action="runTests"]').forEach(n=>n.onclick=()=>runTests(false));document.querySelectorAll('[data-action="runAzureTest"]').forEach(n=>n.onclick=()=>runTests(true));document.querySelectorAll('[data-action="downloadLog"]').forEach(n=>n.onclick=()=>{log("INFO","log_exported",{lines:logLines.length});exportFile("also-diagnostics-"+new Date().toISOString().replace(/[:.]/g,"-")+".log",logHeader()+logLines.join("\n")+"\n","text/plain");toast("Logfile heruntergeladen")});document.querySelectorAll('[data-action="clearLog"]').forEach(n=>n.onclick=()=>{logLines=[];saveLog();log("INFO","log_cleared",{});render();toast("Log gelöscht")});document.querySelectorAll("[data-ai]").forEach(n=>n.onclick=async()=>{const c=state.companies.find(x=>x.company_id===n.dataset.ai);if(!c)return;n.disabled=true;n.textContent="… analysiert";toast("KI-Analyse läuft …");try{const r=await analyzeCompanyAI(c);expandedAI=c.company_id;render();toast("KI-Analyse fertig ("+r.sources.length+" Quelle(n))")}catch(e){log("ERROR","ai_analysis_failed",Object.assign({company:c.company_id,message:e.message},azureCtx()));crawlCompany(c);computeFit(c);save();expandedAI=c.company_id;render();toast("KI fehlgeschlagen – Keyword-Fallback: "+e.message)}});document.querySelectorAll("[data-ai-toggle]").forEach(n=>n.onclick=()=>{expandedAI=(expandedAI===n.dataset.aiToggle)?null:n.dataset.aiToggle;render()});document.querySelectorAll("[data-ai-collapse]").forEach(n=>n.onclick=()=>{expandedAI=null;render()});document.querySelectorAll("[data-ai-refresh]").forEach(n=>n.onclick=async()=>{const c=state.companies.find(x=>x.company_id===n.dataset.aiRefresh);if(!c)return;n.disabled=true;n.textContent="… analysiert";toast("KI-Analyse läuft …");try{await analyzeCompanyAI(c);openCompany(c.company_id);toast("KI-Analyse fertig")}catch(e){log("ERROR","ai_analysis_failed",Object.assign({company:c.company_id,message:e.message},azureCtx()));crawlCompany(c);computeFit(c);save();openCompany(c.company_id);toast("KI fehlgeschlagen – Keyword-Fallback: "+e.message)}});document.querySelectorAll('[data-action="crawlAllAI"]').forEach(n=>n.onclick=async()=>{n.disabled=true;toast("KI-Analyse aller Unternehmen läuft …");let ok=0,fb=0;for(const c of state.companies){try{await analyzeCompanyAI(c);ok++}catch(e){log("ERROR","ai_analysis_failed",{company:c.company_id,message:e.message});crawlCompany(c);computeFit(c);save();fb++}}render();toast("KI-Analyse: "+ok+" ok, "+fb+" Fallback")});document.querySelectorAll('[data-action="addPortal"]').forEach(n=>n.onclick=()=>{state.settings.crawlPortals.push({id:"portal-"+Date.now(),name:"Neues Portal",type:"search",url:"https://beispiel.de/suche?q={q}",enabled:false});save();render()});document.querySelectorAll("[data-portal-del]").forEach(n=>n.onclick=()=>{const i=Number(n.dataset.portalDel);state.settings.crawlPortals.splice(i,1);save();render();toast("Portal entfernt")});document.querySelectorAll('[data-action="saveSources"]').forEach(n=>n.onclick=()=>{state.settings.crawlPortals.forEach((p,i)=>{const en=document.querySelector('[data-portal-enabled="'+i+'"]');const nm=document.querySelector('[data-portal-name="'+i+'"]');const ur=document.querySelector('[data-portal-url="'+i+'"]');if(en)p.enabled=en.checked;if(nm)p.name=nm.value.trim()||p.name;if(ur)p.url=ur.value.trim()});const px=document.querySelector("#setProxy");if(px)state.settings.corsProxy=px.value.trim();save();render();toast("Quellen gespeichert")});document.querySelectorAll('[data-action="closeAI"]').forEach(n=>n.onclick=()=>{state.aiResult=null;save();render()});document.querySelectorAll('[data-action="switchProfile"]').forEach(n=>n.onclick=()=>{const el=document.querySelector("#profSel");if(el&&state.settings.profiles[el.value]){state.settings.activeProfile=el.value;save();render();toast("Profil umgeschaltet")}});document.querySelectorAll('[data-action="addProfile"]').forEach(n=>n.onclick=()=>{const el=document.querySelector("#pfNew");const nm=(el&&el.value.trim())||("Profil "+(Object.keys(state.settings.profiles).length+1));const id="prof-"+Date.now().toString(36);const base=JSON.parse(JSON.stringify(activeProfile()));base.id=id;base.name=nm;state.settings.profiles[id]=base;state.settings.activeProfile=id;save();render();toast("Neues Profil angelegt: "+nm)});document.querySelectorAll('[data-action="delProfile"]').forEach(n=>n.onclick=()=>{const ids=Object.keys(state.settings.profiles);if(ids.length<=1){toast("Mindestens ein Profil muss bestehen.");return}const cur=state.settings.activeProfile;if(!confirm('Profil "'+((state.settings.profiles[cur]||{}).name||cur)+'" löschen?'))return;delete state.settings.profiles[cur];state.settings.activeProfile=Object.keys(state.settings.profiles)[0];save();render();toast("Profil gelöscht")});document.querySelectorAll('[data-action="profilSuche"]').forEach(n=>n.onclick=async()=>{const p=activeProfile();p.branchen=[...document.querySelectorAll("[data-pbranch]:checked")].map(e=>e.getAttribute("data-pbranch"));save();await akqProfilSuche()});document.querySelectorAll('[data-action="saveProfile"]').forEach(n=>n.onclick=()=>{const p=activeProfile();const gv=id=>{const el=document.querySelector(id);return el?el.value:""};const ln=id=>gv(id).split("\n").map(x=>x.trim()).filter(Boolean);var _pn=document.querySelector("#pfName");if(_pn&&_pn.value.trim())p.name=_pn.value.trim();p.branchen=[...document.querySelectorAll("[data-pbranch]:checked")].map(e=>e.getAttribute("data-pbranch"));p.persona=gv("#pfPersona").trim();p.leitfrage=gv("#pfLeit").trim();p.useCases=ln("#pfUse");p.dimensions=ln("#pfDim");p.compliance=ln("#pfComp");p.buyingRoles=ln("#pfRoles");document.querySelectorAll("[data-crit]").forEach(el=>{const i=Number(el.dataset.crit);if(p.scoreCriteria&&p.scoreCriteria[i])p.scoreCriteria[i].weight=Number(el.value)||0});p.bands={A:Number(gv("#pfBandA"))||75,B:Number(gv("#pfBandB"))||55,C:Number(gv("#pfBandC"))||35};save();render();toast("Profil gespeichert")});document.querySelectorAll("[data-learn-guide]").forEach(n=>n.onclick=()=>{const el=document.querySelector("#learnGuide");const v=el?el.value.trim():"";if(!v)return;const L=learnRules();const g=gateLearn("guide",{text:v});if(g.ok){L.guidance.push(v);save();render();toast("Regel global gelernt")}else{L.pending.push({kind:"guide",rule:{text:v},reasons:g.reasons,ts:Date.now()});save();render();toast("Gate: "+g.reasons[0])}});document.querySelectorAll("[data-learn-term]").forEach(n=>n.onclick=()=>{const f=(document.querySelector("#learnFrom")||{}).value,t=(document.querySelector("#learnTo")||{}).value;if(!f||!t)return;const L=learnRules();const g=gateLearn("term",{from:f,to:t});if(g.ok){L.termMap[String(f).trim().toLowerCase()]=String(t).trim();save();render();toast("Normalisierung gelernt")}else{L.pending.push({kind:"term",rule:{from:f,to:t},reasons:g.reasons,ts:Date.now()});save();render();toast("Gate: "+g.reasons[0])}});document.querySelectorAll("[data-learn-neg]").forEach(n=>n.onclick=()=>{const v=(document.querySelector("#learnNeg")||{}).value;if(!v)return;const L=learnRules();const g=gateLearn("neg",{tag:v});if(g.ok){L.negatives.push(String(v).trim());save();render();toast("Fehltreffer gelernt")}else{L.pending.push({kind:"neg",rule:{tag:v},reasons:g.reasons,ts:Date.now()});save();render();toast("Gate: "+g.reasons[0])}});document.querySelectorAll("[data-learn-pos]").forEach(n=>n.onclick=()=>{const c=state.companies.find(x=>x.company_id===n.dataset.learnPos);if(!c)return;const L=learnRules();const tg=tags(c);const bd=(c.fit&&c.fit.band)||c.priority;L.positives.push({name:c.company_name,band:bd,tags:tg});const line="Unternehmen mit Signalen wie "+((tg.slice(0,5).join(", "))||(c.raw_tags||[]).slice(0,5).join(", "))+" sind typischerweise "+bd+"-Accounts.";if((tg.length||(c.raw_tags||[]).length)&&!L.guidance.includes(line))L.guidance.push(line);save();render();toast("Als Positivbeispiel übernommen")});document.querySelectorAll("[data-del-guide]").forEach(n=>n.onclick=()=>{const L=learnRules();L.guidance.splice(Number(n.dataset.delGuide),1);save();render()});document.querySelectorAll("[data-del-term]").forEach(n=>n.onclick=()=>{const L=learnRules();delete L.termMap[n.dataset.delTerm];save();render()});document.querySelectorAll("[data-del-neg]").forEach(n=>n.onclick=()=>{const L=learnRules();L.negatives.splice(Number(n.dataset.delNeg),1);save();render()});document.querySelectorAll("[data-del-pos]").forEach(n=>n.onclick=()=>{const L=learnRules();L.positives.splice(Number(n.dataset.delPos),1);save();render()});document.querySelectorAll("[data-act-pending]").forEach(n=>n.onclick=()=>{const L=learnRules();const idx=Number(n.dataset.actPending);const it=L.pending[idx];if(!it)return;if(it.kind==="guide"){if(!L.guidance.includes(it.rule.text))L.guidance.push(it.rule.text)}else if(it.kind==="term"){L.termMap[String(it.rule.from).trim().toLowerCase()]=String(it.rule.to).trim()}else if(it.kind==="neg"){const t=String(it.rule.tag).trim();if(!L.negatives.includes(t))L.negatives.push(t)}L.pending.splice(idx,1);save();render();toast("Trotz Gate aktiviert")});document.querySelectorAll("[data-disc-pending]").forEach(n=>n.onclick=()=>{const L=learnRules();L.pending.splice(Number(n.dataset.discPending),1);save();render()});document.querySelectorAll("[data-add-nc]").forEach(n=>n.onclick=()=>{const tx=(document.querySelector("#ncText")||{}).value,tg=(document.querySelector("#ncTags")||{}).value;if(!tx||!tg)return;const L=learnRules();L.negativeCorpus.push({text:String(tx).trim(),mustNot:String(tg).split(",").map(x=>x.trim()).filter(Boolean)});save();render();toast("Gegenbeispiel hinzugefügt")});document.querySelectorAll("[data-del-nc]").forEach(n=>n.onclick=()=>{const L=learnRules();L.negativeCorpus.splice(Number(n.dataset.delNc),1);save();render()})}
